(window.EH_ROOMS=window.EH_ROOMS||{})["prehistory"]={"id": "prehistory", "zh": "史前", "lat": "Praehistoria", "yrs": "c. 40,000 – 10,000 BCE", "one": "火光一晃，叠画的腿像跑了起来", "wall": "#3B2A1F", "wallWhy": "墙面取油灯光圈外的深赭褐色岩壁。这些画本来画在照不到日光的洞穴深处，只靠油灯和火把照亮；墙压暗，炭黑的线和赭红的斑才会像在灯下那样浮出来。岩画长在岩壁上，本来没有边框，所以本厅不加框，画面边缘直接融进墙里。", "ink": "light", "frame": "fade", "art": {"img": "main.webp", "w": 2400, "h": 1600, "who": "佚名奥瑞纳文化画者", "whoLat": "Unknown Aurignacian artists", "title": "《狮子壁》中右段（复制品）", "meta": ["约 3.7 万 – 3.35 万年前，木炭线描、手抹晕染、燧石刮边", "整面壁画长十余米，图为中右段", "法国阿尔代什省，肖维洞；图摄于复制洞“肖维 2 号洞”"], "credit": "Wikimedia Commons, File:17 PanneauDesLions(CentreDroit)RhinocérosBisonMamouthRegardentLeChevalDansLaNiche.jpg — 摄影 Claude Valette，CC BY-SA 4.0", "short": "《狮子壁》"}, "lede": "三万多年前，人举着火把走进山洞深处，在岩壁上画下犀牛、野牛、狮子和马。", "work": "这是肖维洞最深处“尽头厅”那面大壁画的中右段。岩壁中间凹进一个小壁龛，里面画着一匹马，犀牛、野牛和一头猛犸象围在四周。线条用木炭画成，形体靠晕染和刮边浮出岩面。右上那头野牛腹下画了一簇张开的腿，壁龛上方也垂着好几条并排的腿线；有研究者认为，灯光一晃，这些腿会轮流显现。", "quote": ["旧石器时代的画者有意让他们的图像活起来。洞穴画里的动物，大多在动。", "马克·阿泽马，史前考古学家，2012 年接受《科学新闻》采访（本展译）"], "origin": "四万五千年前，现代人已来到欧洲；约四万年前起，洞穴壁画、象牙小雕像和骨笛几乎同时出现。肖维洞是其中最早的一批：测年显示人在洞里活动过两期，约 3.7 万至 3.35 万年前和约 3.1 万至 2.8 万年前，多数黑色素描属于第一期。后来洞口塌方封死，画面连同洞熊的骨头和爪痕一起留存下来。1994 年 12 月，三位洞穴探险者发现了它。为避免拉斯科那样因游客过多而长藻受损，原洞从未开放，2015 年在附近建成复制洞，按原大复制了主要壁画。", "traits": [["顺着岩壁画", "画者顺着岩面的鼓包和凹槽落笔：凸起处正好成了动物的肩和腹，壁龛里的马像从洞里探出头来。灯光一移，岩面起伏也跟着变。"], ["叠画的腿", "一只动物画出好几组腿，或多画几条背线、几只角。有研究者认为，灯光晃动时不同的腿轮流被照亮，看上去像在跑。法国 12 个洞里已找到 53 例。"], ["木炭、赭石和手", "黑线用烧过的木头画，红色来自含铁的赭石。画者用手或兽皮把炭粉抹开做出明暗，再用燧石刮掉轮廓外的岩面，让形体浮起。几乎不见涂改。"], ["画动物，很少画人", "肖维洞能认出 14 种动物，狮子、洞熊、犀牛这类危险的大动物特别多。人几乎不出现，只有一处女性下半身、几处女性阴部三角和少量手印。"]], "special": {"title": "你的手印", "type": "handprint", "text": "岩壁上一只空出来、没有颜料的手形，叫“负形手印”。做法是：手贴在岩壁上，把研碎的赭石或炭粉含在嘴里，或装进空心的骨管，对着手吹过去。法国加尔加斯洞约 2.7 万年前留下两百多枚手印，近一半像少了手指，原因至今有争论；阿根廷“手洞”的两千多只手大多是左手，说明吹管多握在右手。", "flicker": {"label": "闪烁速度", "text": "这个滑杆也控制展厅墙上的火光。调慢一些，叠画的腿会一组一组地交替亮起：研究者推测，旧石器时代的“动画”靠的就是晃动的灯火和叠在一起的几组腿。"}, "guides": {"note": "像素坐标以 main.webp（2400 × 1600）为准，原点左上；box 为 [x0, y0, x1, y1]。详见 notes.md", "legs": [{"name": "bison", "box": [1580, 400, 1920, 680]}, {"name": "mammoth", "box": [1760, 820, 2220, 1250]}, {"name": "hanging", "box": [800, 560, 1400, 1000]}, {"name": "leftRhino", "box": [330, 950, 720, 1360]}], "stencil": [1080, 1190, 1560, 1570], "stencilAlt": [960, 20, 1300, 180], "lampCenter": [1300, 800]}}, "works": [{"img": "w1.webp", "w": 730, "h": 1200, "who": "佚名格拉维特文化雕刻者", "whoLat": "Unknown Gravettian carver", "title": "《维伦多夫的维纳斯》", "meta": ["约 2.95 万年前，鲕粒石灰岩，原有红色涂层", "高约 11 cm", "维也纳，自然史博物馆"], "note": "手掌大小的女人像：脸被发辫（或编帽）盖住，身体被放大。", "credit": "Wikimedia Commons, File:Venus of Willendorf frontview retouched 2.jpg — 摄影 Matthias Kabel，修图 AlMare，CC BY 2.5（多重许可之一）"}, {"img": "w2.webp", "w": 1200, "h": 798, "who": "佚名马格德林文化画者", "whoLat": "Unknown Magdalenian artists", "title": "《拉斯科：红牛与小马群》（复制品）", "meta": ["原作约 2.2 万 – 1.7 万年前，赭石、锰黑，喷涂与涂抹", "轴向长廊局部（原作）", "法国多尔多涅省蒙蒂尼亚克，拉斯科二号洞（复制洞）"], "note": "原洞 1963 年起封闭；复制洞 1983 年开放。", "credit": "Wikimedia Commons, File:Lascaux II.jpg — 摄影 Jack Versloot，CC BY 2.0"}, {"img": "w3.webp", "w": 1200, "h": 800, "who": "佚名马格德林文化画者", "whoLat": "Unknown Magdalenian artists", "title": "《阿尔塔米拉：天顶野牛》（复制品）", "meta": ["原作约 1.7 万年前，赭石、赤铁矿、木炭，兼有刻线", "多色天顶所在侧厅约 18 × 9 m（原作）", "西班牙坎塔布里亚，阿尔塔米拉国家博物馆“新洞”（复制洞）"], "note": "借岩顶的鼓包画野牛的肚子，红黑两色晕染出体积。", "credit": "Wikimedia Commons, File:Bisonte en el Techo de Policromos, Neocueva de Altamira.jpg — 摄影 Jl FilpoC，CC BY 4.0"}, {"img": "w4.webp", "w": 1200, "h": 674, "who": "佚名狩猎采集者", "whoLat": "Unknown hunter-gatherers of Patagonia", "title": "《手洞的负形手印》", "meta": ["约公元前 7300 年起分三期绘成，矿物颜料吹喷", "洞口岩壁局部", "阿根廷圣克鲁斯省平图拉斯河谷，手洞（世界遗产）"], "note": "两千多只手，大多是左手：吹管多握在右手。", "credit": "Wikimedia Commons, File:Cueva de las Manos (6811931046).jpg — 摄影 Pablo A. Gimenez，CC BY-SA 2.0"}], "chain": "之前：人已在岩壁上留下手印，印尼苏拉威西东南穆纳岛上的一枚负形手印至少有 6.78 万年。之后：再过一两万年，拉斯科和阿尔塔米拉把洞穴画推向多色和大幅面。农业出现后，图像越来越多地进入神庙和墓室；下一厅的古希腊人开始问，人体怎样才算“对”。", "sources": [{"label": "维基共享资源 · 主图文件页", "claim": "主图文件、摄影者 Claude Valette、CC BY-SA 4.0；说明为“Lions Panel (center right), the niche with horse … Pont d'Arc cave (copy of the Chauvet Cave)”，木炭画、晕染、燧石刮边", "url": "https://commons.wikimedia.org/wiki/File:17_PanneauDesLions(CentreDroit)Rhinoc%C3%A9rosBisonMamouthRegardentLeChevalDansLaNiche.jpg"}, {"label": "英文维基百科 · 肖维洞", "claim": "肖维洞：1994 年 12 月 18 日由 Chauvet、Brunel、Hillaire 发现；两期人类活动约 3.7 万–3.35 万年前与 3.1 万–2.8 万年前，多数黑色素描属第一期；有吹喷的手印；1994 年起不对公众开放（维基只作线索，种数以 Clottes 的 14 种为准）", "url": "https://en.wikipedia.org/wiki/Chauvet_Cave"}, {"label": "法国文化部肖维洞网站 · 大狮子壁", "claim": "尽头厅狮子壁右段：狮群追猎野牛，墙面先刮净再作画，画成时间短（法国文化部肖维洞官方网站）", "url": "https://archeologie.culture.gouv.fr/chauvet/en/large-lion-panel"}, {"label": "法兰西艺术院 · 克洛特 2010 年报告", "claim": "尽头厅大壁：壁龛里的马居中，左侧十八头犀牛，两侧狮群；刮边（détourage）与手或兽皮抹开的晕染（estompe）；几乎没有涂改；八腿野牛“像在走”，是表现运动还是两头叠画“不能确定”；洞内共 14 种动物，狮、犀、猛犸、熊约占可辨动物七成；人们用火把（欧洲赤松）照明（Jean Clottes，法兰西艺术院 2010 年报告）。壁画长度 Clottes 说约 10 米", "url": "https://www.academiedesbeauxarts.fr/sites/default/files/inline-files/06-2010-Clottes.pdf"}, {"label": "Google 艺术与文化 · 肖维洞尽头厅", "claim": "狮子壁长约 49 英尺（约 15 米）；尽头厅唯一的人形是一处女性下半身（Google Arts & Culture，肖维 2 号洞供稿）。与上条长度说法不一，故写“十余米”", "url": "https://artsandculture.google.com/story/the-end-chamber-grotte-chauvet/8QVRQAObSOFYJw?hl=en"}, {"label": "《古民族学》期刊 · 阿泽马论洞穴画的动画", "claim": "叠画分解运动：阿泽马称肖维的“八腿野牛”证明奥瑞纳时期已用此法，但他把这头野牛定位在“狮子小室”（Alcôve des Lions），不在尽头厅；故本厅只描述主图中可见的多腿线，不称其即为文献中的八腿野牛", "url": "https://blogs.univ-tlse2.fr/palethnologie/wp-content/files/2013/fr-FR/version-longue/articles/EUR06_Azema.pdf"}, {"label": "《科学新闻》· 石器时代艺术动了起来", "claim": "法国 12 个洞中 53 个形象叠画两幅以上以表现奔跑、甩头、甩尾；火把晃动增强动感；阿泽马引语原文：“Stone Age artists intended to give life to their images … The majority of cave drawings show animals in action.”", "url": "https://www.sciencenews.org/article/stone-age-art-gets-animated"}, {"label": "《古代》期刊 · 阿泽马与里维尔 2012", "claim": "Azéma & Rivère 2012, Animation in Palaeolithic art: a pre-echo of cinema, Antiquity 86", "url": "https://www.cambridge.org/core/journals/antiquity/article/animation-in-palaeolithic-art-a-preecho-of-cinema/50BB05A3FDED8AC8CB5F5126249090F9"}, {"label": "英文维基百科 · 肖维复制洞", "claim": "复制洞原名 Caverne du Pont-d'Arc，后更名 Grotte Chauvet 2 – Ardèche", "url": "https://en.wikipedia.org/wiki/Caverne_du_Pont-d%27Arc"}, {"label": "维也纳自然史博物馆 · 维纳斯研究", "claim": "维伦多夫的维纳斯：约 29,500 年前，高 11 cm，鲕粒岩，1908 年 8 月 7 日出土，表面有红色涂层（维也纳自然史博物馆）", "url": "https://www.nhm.at/en/research/prehistory/research/venus-research"}, {"label": "英文维基百科 · 维伦多夫的维纳斯", "claim": "同上：鲕粒石灰岩，石料非本地所产；藏维也纳自然史博物馆（维基作线索；高度以博物馆的 11 cm 为准）", "url": "https://en.wikipedia.org/wiki/Venus_of_Willendorf"}, {"label": "维基共享资源 · 维纳斯图片文件页", "claim": "w1 图片：摄影 User:MatthiasKabel，修图 User:AlMare；GFDL / CC BY-SA 3.0 / CC BY 2.5 多重许可，本展取 CC BY 2.5", "url": "https://commons.wikimedia.org/wiki/File:Venus_of_Willendorf_frontview_retouched_2.jpg"}, {"label": "英文维基百科 · 拉斯科洞", "claim": "拉斯科：约 1.7 万–2.2 万年前；1940 年发现；1963 年因游客呼出的二氧化碳、热和湿气导致藻类、真菌滋生而封闭；颜料为赭石、赤铁矿、针铁矿、含锰黑；有吹喷；拉斯科二号洞 1983 年开放", "url": "https://en.wikipedia.org/wiki/Lascaux"}, {"label": "法国文化部拉斯科网站 · 拉斯科二号洞", "claim": "拉斯科二号洞复制公牛厅与轴向长廊，1983 年开放（法国文化部拉斯科官方网站）", "url": "https://archeologie.culture.gouv.fr/lascaux/en/lascaux-ii-and-iii"}, {"label": "密歇根大学艺术史图库 · 拉斯科轴向长廊", "claim": "“红牛与小黑马”位于轴向长廊（密歇根大学艺术史图库条目）。w2 画面据此辨认，属本展判断", "url": "https://quod.lib.umich.edu/h/hart/x-691355/04d100072"}, {"label": "维基共享资源 · 拉斯科图片文件页", "claim": "w2 图片与 CC BY 2.0 许可，说明为“Reproductions of some Lascaux artworks in Lascaux II”", "url": "https://commons.wikimedia.org/wiki/File:Lascaux_II.jpg"}, {"label": "英文维基百科 · 阿尔塔米拉洞", "claim": "阿尔塔米拉：多色天顶属马格德林文化；颜料为木炭、赭石或赤铁矿；复制洞 2001 年建成，属阿尔塔米拉国家博物馆与研究中心", "url": "https://en.wikipedia.org/wiki/Cave_of_Altamira"}, {"label": "布拉德肖基金会 · 阿尔塔米拉洞", "claim": "阿尔塔米拉：先刻轮廓再画，借岩顶天然鼓包表现体积；本页未能核到原先引用的“14,820–13,130”与“18 × 9 米”，这两项改据下列来源", "url": "https://www.bradshawfoundation.com/spain/altamira/index.php"}, {"label": "维基共享资源 · 阿尔塔米拉图片文件页", "claim": "w3 图片与 CC BY 4.0 许可，拍摄于 Neocueva 复制洞", "url": "https://commons.wikimedia.org/wiki/File:Bisonte_en_el_Techo_de_Policromos,_Neocueva_de_Altamira.jpg"}, {"label": "英文维基百科 · 手洞", "claim": "手洞：2000 多只手，829 只左手对 31 只右手；骨管喷涂；1999 年列入世界遗产；位于圣克鲁斯省平图拉斯河谷（维基作线索；分期以 Britannica 为准）", "url": "https://en.wikipedia.org/wiki/Cave_of_the_Hands"}, {"label": "维基共享资源 · 手洞图片文件页", "claim": "w4 图片与 CC BY-SA 2.0 许可", "url": "https://commons.wikimedia.org/wiki/File:Cueva_de_las_Manos_(6811931046).jpg"}, {"label": "英文维基百科 · 加尔加斯洞", "claim": "加尔加斯洞：手印墙缝中骨头测年约 2.7 万年前（格拉维特期）；缺指原因有疾病、冻伤、截指仪式等假说，多数研究者倾向于弯曲手指的象征说法", "url": "https://en.wikipedia.org/wiki/Caves_of_Gargas"}, {"label": "布拉德肖基金会 · 缺指的手印", "claim": "加尔加斯约 231 枚手印，其中 114 枚缺一根或几根手指", "url": "https://www.bradshawfoundation.com/hands/hand_stencils_missing_fingers/index.php"}, {"label": "《自然》· 苏拉威西最早的岩画手印（2026）", "claim": "穆纳岛（苏拉威西东南外海）Liang Metanduno 洞一枚负形手印，其上钙华 U 系测年给出最低年龄 6.78 万年，为已知最早的岩画（Oktaviana 等，Nature，2026 年 1 月）", "url": "https://www.nature.com/articles/s41586-025-09968-y"}, {"label": "《美国科学院院刊》· 肖维洞测年（2016）", "claim": "肖维洞两期：奥瑞纳期约 3.7 万–3.35 万年前、格拉维特期约 3.1 万–2.8 万年前（校正年），多数黑色素描属第一期（Quiles 等，PNAS 113(17), 2016）", "url": "https://www.pnas.org/doi/10.1073/pnas.1523158113"}, {"label": "布拉德肖基金会 · 肖维洞的“维纳斯与巫师”", "claim": "肖维洞人形：尽头厅垂岩上一处女性下半身（与野牛人“巫师”相叠），另有四处只画阴部三角的女性形象（Bradshaw Foundation，据 Clottes）", "url": "https://www.bradshawfoundation.com/chauvet/venus_sorcerer.php"}, {"label": "布拉德肖基金会 · 肖维复制洞的做法", "claim": "复制洞：原洞地面约 8,400 m²，复制洞压缩为 3,000 m²；选出的装饰区按原大复制；2015 年开放时名为 Caverne du Pont-d'Arc", "url": "https://www.bradshawfoundation.com/rockartnetwork/methods_strategies_replica_chauvet.php"}, {"label": "法国文化部肖维洞网站 · 复制洞工程", "claim": "复制洞 Grotte Chauvet 2 地面 3,000 m²、8,200 m² 展开面；原洞无法整体复制，只选重要部分（法国文化部肖维洞网站）", "url": "https://archeologie.culture.gouv.fr/chauvet/en/grand-project"}, {"label": "Franceinfo · 复制洞更名“肖维 2 号洞”", "claim": "2019 年 Caverne du Pont-d'Arc 更名为 Grotte Chauvet 2 – Ardèche", "url": "https://www.franceinfo.fr/culture/patrimoine/la-caverne-du-pont-d-arc-s-appelle-desormais-grotte-chauvet-2-ardeche_3383813.html"}, {"label": "《自然》· 巴乔基罗洞的早期现代人（2020）", "claim": "现代人约 4.5 万年前已到欧洲中纬度（保加利亚巴乔基罗洞，Hublin 等，Nature 581, 2020）", "url": "https://www.nature.com/articles/s41586-020-2259-z"}, {"label": "法国文化部拉斯科网站 · 轴向长廊的红牛", "claim": "拉斯科“红牛黑头”（vache à collerette）是进入轴向长廊后的第一个形象（法国文化部拉斯科网站图库）", "url": "https://archeologie.culture.gouv.fr/lascaux/en/mediatheque/die-kuh-mit-der-halskrause"}, {"label": "西班牙文维基百科 · 阿尔塔米拉洞", "claim": "阿尔塔米拉多色画：碳十四测年平均约 14,000 BP（木炭）、14,450 BP（腐殖质部分），均为未校正值，校正后约 1.7 万年前；大厅约 18 × 9 米", "url": "https://es.wikipedia.org/wiki/Cueva_de_Altamira"}, {"label": "阿尔塔米拉国家博物馆 · 洞中的艺术", "claim": "阿尔塔米拉洞内艺术跨度约 3.6 万–1.3 万年前；多色厅大型野牛长 125–170 cm；先刻轮廓，再用木炭勾线，填红或黄色，眼、角等处用刻线（阿尔塔米拉国家博物馆）", "url": "https://www.cultura.gob.es/mnaltamira/cueva-altamira/arte.html"}, {"label": "大英百科全书 · 手洞", "claim": "手洞三期：A 组始于约公元前 7300 年，B 组约公元前 5000 年，C 组始于约公元 700 年（Britannica，据 Gradin；网页 403，内容经搜索摘要核对）", "url": "https://www.britannica.com/place/Cueva-de-las-Manos"}, {"label": "联合国教科文组织 · 手洞世界遗产", "claim": "UNESCO 称手洞岩画作于 1.3 万至 9500 年前，与 Britannica 分期不一致，见 factcheck.md", "url": "https://whc.unesco.org/en/list/936/"}, {"label": "大英百科全书 · 维伦多夫的维纳斯", "claim": "维伦多夫的维纳斯头部：发辫或编织帽两说（本展措辞据此写“发辫（或编帽）”）", "url": "https://www.britannica.com/topic/Venus-of-Willendorf"}, {"label": "法国文化部拉斯科网站 · 颜料与原料", "claim": "拉斯科颜料：红为赤铁矿、黄为针铁矿；本地区黑色一律是锰氧化物，不同于阿尔代什等地多用木炭（法国文化部拉斯科网站）", "url": "https://archeologie.culture.gouv.fr/lascaux/en/raw-materials"}]};

