(window.EH_ROOMS=window.EH_ROOMS||{})["antiquity"]={"id": "antiquity", "zh": "古希腊罗马", "lat": "Antiquitas classica", "yrs": "c. 600 BCE – 300 CE", "one": "重心落到一条腿上，石头就活了", "wall": "#ECE5D8", "wallWhy": "墙面取暖白石灰岩的颜色，呼应大理石和石灰岩这两种古典雕刻材料；原作本来有彩绘，大多已褪。雕像立在地上，从各个方向都能看，本来就没有画框，所以本厅不加框。", "ink": "dark", "frame": "none", "art": {"img": "main_cut.webp", "w": 810, "h": 2190, "who": "波留克列特斯（原作）", "whoLat": "Polykleitos of Argos, active c. 460 – 415 BCE (Roman copy)", "title": "《持矛者》（罗马复制品）", "meta": ["公元前 27 年 – 公元 68 年，彭特利孔大理石", "198.1 × 48.3 × 48.3 cm", "明尼阿波利斯美术馆（86.6）"], "credit": "Wikimedia Commons, File:Doryphoros MIA 866.jpg — 来源 明尼阿波利斯美术馆，公有领域", "short": "《持矛者》"}, "lede": "公元前 5 世纪，阿尔戈斯雕塑家波留克列特斯用一尊青年立像回答了一个问题：人体怎样才算“对”。", "work": "一个裸体青年向前迈了半步。重心压在右腿上，右髋因此抬高；左腿放松，向后撤。肩线朝相反方向倾斜，头转向右侧。左手原本握着一支矛，现已失去。这种合乎人站立时重心分配的姿势，后来称为“对立平衡”（contrapposto）。青铜原作约作于公元前 450–440 年，已失。眼前是罗马人约四五百年后的大理石复制品；腿边的树桩、手与大腿间的小横杆，都是大理石为承重加的支撑。", "quote": ["美不在于构成身体的各元素之间的比例，而在于各部分之间的比例：手指与手指，手指与手掌、手腕，这些与前臂，前臂与上臂，一切与一切——正如波留克列特斯的《法则》所写。", "盖伦《论希波克拉底与柏拉图的学说》5.3，转述克吕西波（据英译转述，非逐字）"], "origin": "公元前 7 世纪，希腊人与埃及往来增多，雕塑家学到了在石料上按网格定比例的做法，也学到了那个姿势：正面直立，左脚前伸，双臂贴身。这就是库罗斯（kouros，意为“青年”），常立在墓前，或献给神庙。此后一百多年，膝盖、肋骨、腹肌越刻越像真人。约公元前 480 年的《克里提奥斯少年》是现存最早把重心放到一条腿上的石像之一。到公元前 5 世纪中叶，观察变成了方法：波留克列特斯写下比例，菲迪亚斯主持帕特农神庙的雕刻。", "traits": [["重心落在一条腿上", "承重腿一侧的髋抬高，同侧肩膀下沉，躯干形成轻微的 S 形。静止的石像第一次显得随时能迈步，这种站法叫对立平衡。"], ["美可以计算", "波留克列特斯认为美来自部分与部分、部分与整体之间的比例，从指节一直推到全身。他把这套比例写成《法则》，再做一尊像来示范。"], ["理想化的身体", "古典雕像很少刻画某个具体的人的皱纹和缺陷。神、英雄和运动员用的是同一种“完美”的身体：像真人，但比真人更匀称。"], ["罗马：复制、肖像、宣传", "罗马人大量复制希腊雕像，也把希腊式的身体配上可辨认的本人头像。奥古斯都像借用持矛者的站姿，把皇帝塑造成不会老的英雄。"]], "special": {"title": "从库罗斯到持矛者", "type": "contrapposto", "with": "kouros.webp", "withW": 1524, "withH": 2400, "withTitle": "《库罗斯（青年立像）》", "withWho": "佚名阿提卡雕塑家", "withMeta": ["约公元前 590–580 年，纳克索斯大理石", "高 194.6 cm（不含底座）", "纽约，大都会艺术博物馆（32.11.1）"], "withCredit": "Wikimedia Commons, File:Marble statue of a kouros (youth) MET DT247656.jpg — 来源 大都会艺术博物馆，CC0", "text": "库罗斯约作于公元前 590–580 年。他左脚前伸，但两腿平均承重，肩线和髋线都是水平的，身体左右对称，像一根立柱。持矛者晚了约 140 年：重心压在右腿，右髋抬高、右肩下沉，肩线与髋线朝相反方向倾斜，在身体一侧收拢、另一侧张开。看这两条线就能分辨两种站姿：库罗斯按规定站立，持矛者按观察站立。", "rows": [["重心", "两腿平均", "压在右腿"], ["肩线", "水平", "向右肩一侧下斜"], ["髋线", "水平", "向右髋一侧上抬，与肩线相反"], ["头", "正对前方", "转向右侧，略低"], ["手臂", "贴身，握拳", "一臂垂下，一臂持矛（已失）"]], "guides": {"note": "像素坐标以各自 webp 原尺寸为准；'右'指雕像本人的右侧（观者左侧）", "kouros": {"shoulder": [[555, 600], [995, 600]], "hip": [[625, 1050], [915, 1050]]}, "main": {"shoulder": [[660, 575], [1160, 550]], "hip": [[705, 990], [1095, 1040]]}}}, "works": [{"img": "w1.webp", "w": 1200, "h": 699, "who": "菲迪亚斯（总设计）及其作坊", "whoLat": "Pheidias, c. 480 – c. 430 BCE, and workshop", "title": "《帕特农西饰带：两名骑手》", "meta": ["公元前 438–432 年，彭特利孔大理石浅浮雕", "西饰带第 II 块，饰带高约 102 cm", "伦敦，大英博物馆（1816,0610.47）"], "note": "浅浮雕里的骑手回身、马匹后仰，队伍在动。", "credit": "Wikimedia Commons, File:Cavalcade west frieze Parthenon BM.jpg — 摄影 Jastrow，公有领域"}, {"img": "w2.webp", "w": 1128, "h": 1200, "who": "阿格桑德罗斯等三位罗得岛雕塑家（据老普林尼）", "whoLat": "Hagesandros, Athanodoros & Polydoros of Rhodes (dates unknown)", "title": "《拉奥孔和他的儿子们》", "meta": ["约公元前 40–30 年（馆方定年；或为复制品），大理石", "208 × 163 × 112 cm", "梵蒂冈城，梵蒂冈博物馆庇护-克莱孟博物馆（1059）"], "note": "希腊化时期：平衡让位给扭转和痛苦。", "credit": "Wikimedia Commons, File:Laocoon Pio-Clementino Inv1059-1064-1067.jpg — 摄影 Marie-Lan Nguyen，公有领域"}, {"img": "w3.webp", "w": 800, "h": 1200, "who": "佚名罗马雕塑家", "whoLat": "Unknown Roman sculptor", "title": "《普里马波尔塔的奥古斯都》", "meta": ["公元 1 世纪初，大理石，有彩绘残迹", "高约 208 cm", "梵蒂冈城，梵蒂冈博物馆新翼（2290）"], "note": "持矛者的站姿，皇帝的脸和铠甲；一般认为仿自一尊已失的青铜像。", "credit": "Wikimedia Commons, File:Statue-Augustus.jpg — 摄影 Till Niermann，公有领域"}, {"img": "w4.webp", "w": 1069, "h": 1200, "who": "佚名庞贝画师", "whoLat": "Unknown Pompeian painter", "title": "《泰伦提乌斯·尼奥与妻子》", "meta": ["约公元 55–79 年（馆方定年），湿壁画", "65 × 58 cm", "那不勒斯，那不勒斯国家考古博物馆（9058）"], "note": "一对普通夫妇，手持书卷和蜡板，想显得有学问。", "credit": "Wikimedia Commons, File:MANNapoli 9058 couple painting.jpg — 摄影 Jebulon，CC0"}], "chain": "之前：库罗斯的正面站姿和网格比例来自埃及。之后：罗马复制品把希腊式的身体带到整个地中海；中世纪欧洲的人像大多又回到正面、扁平。15 世纪起，多纳泰罗、米开朗琪罗重新用起对立平衡；1506 年拉奥孔在罗马出土。文艺复兴接回了古典的身体。", "sources": [{"label": "明尼阿波利斯美术馆 · 持矛者藏品数据", "claim": "明尼阿波利斯《持矛者》：标题、年代 27 BCE–68 CE、彭特利孔大理石、198.12 × 48.26 × 48.26 cm、编号 86.6、Roman copy of a Greek bronze c. 450–440 BCE、Polykleitos active 460–415 BCE、Public Domain（馆方开放数据 API）", "url": "https://search.artsmia.org/id/3520"}, {"label": "明尼阿波利斯美术馆 · 持矛者藏品页", "claim": "同上，馆方网页", "url": "https://collections.artsmia.org/art/3520/the-doryphoros-unknown-roman"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图文件及 PD 许可", "url": "https://commons.wikimedia.org/wiki/File:Doryphoros_MIA_866.jpg"}, {"label": "英文维基百科 · 持矛者", "claim": "持矛者：原作青铜约公元前 440 年已失；右腿承重、左腿放松、头转向右侧；示范《法则》；那不勒斯复制品出自庞贝", "url": "https://en.wikipedia.org/wiki/Doryphoros"}, {"label": "英文维基百科 · 波留克列特斯", "claim": "波留克列特斯：阿尔戈斯人；Philo 引‘完美由许多数字一点点达成’；盖伦论 symmetria", "url": "https://en.wikipedia.org/wiki/Polykleitos"}, {"label": "Perseus 数字图书馆 · 盖伦《论希波克拉底与柏拉图的学说》", "claim": "盖伦《论希波克拉底与柏拉图的学说》5.3 转述克吕西波：美在于手指与手指……一切与一切的比例，‘正如波留克列特斯的《法则》所写’（希腊原文见 Perseus/Scaife；英译转述）", "url": "https://scaife.perseus.org/library/urn:cts:greekLit:tlg0057.tlg032/"}, {"label": "英文维基百科 · 对立平衡", "claim": "对立平衡定义；《克里提奥斯少年》约公元前 480 年为最早实例；文艺复兴由多纳泰罗等复兴", "url": "https://en.wikipedia.org/wiki/Contrapposto"}, {"label": "大都会艺术博物馆 · 库罗斯藏品数据", "claim": "纽约库罗斯：约公元前 590–580 年、阿提卡、纳克索斯大理石、194.6 cm（不含底座）、肩宽 51.6 cm、编号 32.11.1、Fletcher Fund 1932、公有领域（大都会开放 API）；大都会开放 API 复核：ca. 590–580 BCE，Marble, Naxian，194.6 cm（height w/o plinth），32.11.1，Greek, Attic，isPublicDomain", "url": "https://collectionapi.metmuseum.org/public/collection/v1/objects/253370"}, {"label": "大都会艺术博物馆 · 库罗斯藏品页", "claim": "同上，馆方网页；姿势与比例受埃及影响，立于一位雅典贵族青年墓前", "url": "https://www.metmuseum.org/art/collection/search/253370"}, {"label": "英文维基百科 · 纽约库罗斯", "claim": "纽约库罗斯：左腿前伸、双臂贴身的站姿来自埃及（维基引大都会希腊罗马部）；另有文献定年约公元前 600–590 年", "url": "https://en.wikipedia.org/wiki/New_York_Kouros"}, {"label": "维基共享资源 · 库罗斯图片文件页", "claim": "库罗斯图片文件及 CC0 许可", "url": "https://commons.wikimedia.org/wiki/File:Marble_statue_of_a_kouros_(youth)_MET_DT247656.jpg"}, {"label": "大英博物馆 · 帕特农西饰带第 II 块", "claim": "帕特农神庙西饰带第 II 块：大英博物馆编号 1816,0610.47，菲迪亚斯设计，两名骑手勒马、前者回头", "url": "https://www.britishmuseum.org/collection/object/G_1816-0610-47"}, {"label": "英文维基百科 · 帕特农饰带", "claim": "帕特农饰带：公元前 438–432 年（大英博物馆）、彭特利孔大理石浅浮雕、高约 1 m、长约 160 m", "url": "https://en.wikipedia.org/wiki/Parthenon_Frieze"}, {"label": "大英博物馆 · 帕特农雕刻", "claim": "帕特农雕刻总体说明（大英博物馆）", "url": "https://www.britishmuseum.org/about-us/british-museum-story/contested-objects-collection/parthenon-sculptures"}, {"label": "梵蒂冈博物馆 · 《拉奥孔》", "claim": "拉奥孔：1506 年出土于罗马埃斯奎利诺山，尤利乌斯二世购得，定年约公元前 40–30 年，编号 1059", "url": "https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/museo-pio-clementino/Cortile-Ottagono/laocoonte.html"}, {"label": "英文维基百科 · 拉奥孔和他的儿子们", "claim": "拉奥孔：208 × 163 × 112 cm；原作/复制品之争，年代提议从公元前 200 年到公元 70 年代；老普林尼记三位罗得岛雕塑家", "url": "https://en.wikipedia.org/wiki/Laoco%C3%B6n_and_His_Sons"}, {"label": "梵蒂冈博物馆 · 《普里马波尔塔的奥古斯都》", "claim": "奥古斯都像：公元 1 世纪初，出土于普里马波尔塔的莉薇娅别墅，受持矛者启发，胸甲表现帕提亚人归还军旗，编号 2290；奥古斯都像（梵蒂冈）：'dated to the beginning of the 1st century A.D.'，出自普里马波尔塔莉薇娅别墅，'seems to have been inspired by the Doryphoros'，Cat. 2290，新翼", "url": "https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/braccio-nuovo/Augusto-di-Prima-Porta.html"}, {"label": "英文维基百科 · 普里马波尔塔的奥古斯都", "claim": "奥古斯都像：高 2.08 m，1863 年 4 月 20 日出土，一般认为仿自青铜原作，有彩绘残迹（梵蒂冈在线目录未能访问，高度以此为准）", "url": "https://en.wikipedia.org/wiki/Augustus_of_Prima_Porta"}, {"label": "英文维基百科 · 泰伦提乌斯·尼奥夫妇像", "claim": "泰伦提乌斯·尼奥夫妇像：出自庞贝 VII.2.6，那不勒斯考古博物馆 9058，约公元 50 年；曾被误称为帕奎乌斯·普罗库鲁斯像；男持书卷、女持笔与蜡板", "url": "https://en.wikipedia.org/wiki/Portrait_of_Terentius_Neo"}, {"label": "维基数据 · 泰伦提乌斯·尼奥夫妇像", "claim": "泰伦提乌斯·尼奥夫妇像：Wikidata 记 58 × 53 cm、约公元 20 年代至 79 年（与馆方数据不一致，以馆方为准）", "url": "https://www.wikidata.org/wiki/Q3399457"}, {"label": "维基共享资源 · 帕特农饰带图片文件页", "claim": "帕特农饰带、拉奥孔、奥古斯都、泰伦提乌斯·尼奥图片的 Commons 文件页（许可见各 credit）", "url": "https://commons.wikimedia.org/wiki/File:Cavalcade_west_frieze_Parthenon_BM.jpg"}, {"label": "维基共享资源 · 拉奥孔图片文件页", "claim": "图片文件及许可", "url": "https://commons.wikimedia.org/wiki/File:Laocoon_Pio-Clementino_Inv1059-1064-1067.jpg"}, {"label": "维基共享资源 · 奥古斯都图片文件页", "claim": "图片文件及许可", "url": "https://commons.wikimedia.org/wiki/File:Statue-Augustus.jpg"}, {"label": "维基共享资源 · 尼奥夫妇像图片文件页", "claim": "图片文件及许可", "url": "https://commons.wikimedia.org/wiki/File:MANNapoli_9058_couple_painting.jpg"}, {"label": "那不勒斯国家考古博物馆（Google 艺术与文化）· 尼奥夫妇像", "claim": "泰伦提乌斯·尼奥夫妇像（馆方经 Google Arts & Culture 发布）：Inv. 9058，55–79 d.C.，65 × 58 cm，出自庞贝，LXXVIII 厅", "url": "https://artsandculture.google.com/asset/terentius-neo-e-la-moglie/5wE6mCTFmiAj0Q"}, {"label": "卫城博物馆 · 克里提奥斯少年", "claim": "克里提奥斯少年（卫城博物馆 Ακρ. 698）：After 480 BC，帕罗斯大理石，高 1.22 m，左腿承重、右腿放松", "url": "https://www.theacropolismuseum.gr/en/youth-statue-kritios-boy"}, {"label": "卫城博物馆 · 帕特农饰带", "claim": "帕特农饰带：115 块、全长 160 m、设计出自菲迪亚斯（卫城博物馆；该馆定雕刻年代为公元前 443–438 年，大英博物馆定为 438–432 年）", "url": "https://www.theacropolismuseum.gr/en/sculptural-decoration/frieze"}, {"label": "大英博物馆（Google 艺术与文化）· 西饰带骑手", "claim": "帕特农西饰带第 II 块：-438/-432，1816,0610.47，骑手勒马、前者向同伴示意（大英博物馆经 Google Arts & Culture）", "url": "https://artsandculture.google.com/asset/horsemen-from-the-west-frieze-of-the-parthenon/dgEf56QqL64Erw?hl=en"}, {"label": "纽约州立大学奥尼昂塔分校课程页 · 持矛者", "claim": "盖伦 De placitis 5.3 英译（Oneonta 课程页引文）：beauty resides not in the commensurability of the constituents but of the parts … finger to finger … everything to everything, as it is written in the Canon of Polyclitus；他据此做了一尊像，也称《法则》", "url": "http://employees.oneonta.edu/farberas/arth/ARTH209/Doyphoros.html"}]};

