(window.EH_ROOMS=window.EH_ROOMS||{})["medieval"]={"id": "medieval", "zh": "中世纪", "lat": "Medium Aevum", "yrs": "c. 500 – 1400", "one": "越神圣，画得越大；金色就是天堂", "wall": "#2A2320", "wallWhy": "近黑的暖褐色，取自烛光照着的教堂石墙。这些画原本就挂在昏暗的教堂里，只靠蜡烛和窗光照亮；深墙让金底和光环像在烛光下那样亮起来。选金色墙会和画上的金底撞在一起，反而看不出金的作用。", "ink": "light", "frame": "gilt", "art": {"img": "main.webp", "w": 1340, "h": 2400, "who": "契马布埃", "whoLat": "Cimabue (Cenni di Pepo), c. 1240 – 1302", "title": "《圣三一圣母》（圣三一大祭坛画）", "meta": ["约 1290–1300 年（年代有争议），木板蛋彩，金底", "384 × 223 cm", "佛罗伦萨，乌菲齐美术馆（Inv. 1890 n. 8343）"], "credit": "Wikimedia Commons, File:Cimabue - Maestà di Santa Trinita - Google Art Project.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）", "short": "《圣三一圣母》"}, "lede": "中世纪的画不模仿眼前的世界，而是把看不见的天国按座次排给人看。", "work": "圣母坐在象牙色的高大宝座上，右手指向怀中的基督，这是拜占庭“指路圣母”的传统姿势。两侧八位天使层层叠起，扶着宝座。宝座下的拱洞里是四位旧约先知，从左到右是耶利米、亚伯拉罕、大卫、以赛亚，手持经卷，意思是旧约托起新约。背景是整片刻了花纹的金箔，没有天空，也没有地平线。圣母画得比天使和先知大得多，因为她更神圣，不是因为离我们更近。", "quote": ["契马布埃以为自己在画坛独占鳌头，如今喝彩归了乔托，他的名声便暗了下去。", "但丁《神曲·炼狱篇》第十一歌 94–96 行（本展译）"], "origin": "476 年西罗马帝国灭亡后，古罗马那种写实的雕像和带纵深的壁画在西欧大多失传。东边的拜占庭保住了另一套传统：人物正面、平面、衬着金底，画像被当作通向神圣者的窗口。约 600 年，教宗格里高利一世写信说，图画之于不识字的人，就像文字之于识字的人。修道院的修士把凯尔特缠绕纹画进经书；12 世纪起城市兴建哥特式大教堂，1144 年落成的圣德尼修道院唱诗堂用大窗把彩色的光引进教堂。意大利画家学的是“希腊样式”，也就是拜占庭画法，契马布埃就从这里起步。", "traits": [["大小按神圣排", "人物画多大，看的是地位：基督和圣母最大，天使、圣徒次之，凡人最小。大小表示谁更重要，和离观者远近无关。"], ["金底代替天空", "背景铺金箔，不画风景，也没有地平线。金子在烛光里会闪，画面就被放进一个不属于人间、也没有具体时刻的地方。"], ["正面、平面、有程式", "人物多半正面直视，身体扁平，衣褶按固定的线条套路来画。画家照前人的范本画，要的是一眼能认出、合乎规矩，不求个人风格。"], ["画长在教堂和经书里", "绘画大多依附于别的东西：马赛克贴在墙上，彩色玻璃嵌进石窗，插图画在手抄本里。大多数作品没有留下作者名字，出自匿名工匠和修士。"]], "special": {"title": "谁更大，谁更神圣", "type": "hierarchy", "text": "中世纪画家不按“近大远小”来画。量一量这幅画：圣母的脸从眉心到嘴约 87 像素，天使 45–53 像素，先知 42–48 像素；她的脸是他们的 1.6–2.1 倍，面积约 3–4 倍。可先知在宝座下方最前面，位置并不比圣母远。这里的大小是一种排名：越神圣，画得越大。到乔托和文艺复兴，大小才重新交给距离和透视来决定。", "boxFormat": "[x0, y0, x1, y1]，main.webp 像素坐标（1340 × 2400），原点在左上", "boxes": [{"key": "madonna", "label": "圣母", "figure": [360, 190, 1010, 1670], "head": [565, 200, 800, 425], "faceBrowToMouth": 87, "note": "坐姿全身（含怀中基督的位置）；head 含头巾"}, {"key": "angel", "label": "天使（左下）", "figure": [20, 940, 300, 1800], "head": [75, 965, 200, 1095], "faceBrowToMouth": 45, "note": "站立全身，是八位天使中最完整的一位"}, {"key": "prophet", "label": "先知亚伯拉罕", "figure": [410, 1980, 660, 2400], "head": [480, 2025, 600, 2160], "faceBrowToMouth": 42, "note": "半身像，下缘被画框截断"}], "ratio": {"madonnaToAngel": 1.9, "madonnaToProphet": 2.1, "basis": "眉心到嘴的垂直距离；站着的天使全身约 860 px，而圣母坐着就有约 1480 px"}}, "works": [{"img": "w1.webp", "w": 1200, "h": 850, "who": "佚名拜占庭镶嵌匠", "whoLat": "Unknown Byzantine mosaicists", "title": "《查士丁尼皇帝与随从》", "meta": ["约 547 年，玻璃与石料镶嵌", "尺寸不详", "拉文纳，圣维塔莱教堂后殿"], "note": "皇帝戴光环站在正中，政权和神权同在一面金墙上。", "credit": "Wikimedia Commons, File:Justinian mosaic, San Vitale, consecrated 547, Ravenna, Italy.jpg — 摄影 Steven Zucker（Smarthistory），CC BY 2.0"}, {"img": "w2.webp", "w": 865, "h": 1200, "who": "佚名修士（爱奥那或凯尔斯）", "whoLat": "Unknown Insular monks (Iona or Kells)", "title": "《凯尔经》Chi-Rho 页", "meta": ["约 800 年，犊皮纸彩绘", "第 34 叶正面，整页约 33 × 25.5 cm", "都柏林，圣三一学院图书馆（MS 58）"], "note": "基督名的两个希腊字母占满整页，纹样里藏着猫和老鼠。", "credit": "Wikimedia Commons, File:KellsFol034rChiRhoMonogram.jpg — 公有领域（PD-Art, PD-old-100）"}, {"img": "w3.webp", "w": 867, "h": 1200, "who": "佚名玻璃匠", "whoLat": "Unknown glaziers", "title": "《北玫瑰窗》", "meta": ["约 1230–1235 年，彩色玻璃", "玫瑰窗直径约 10.5 m", "沙特尔，圣母主教座堂北耳堂"], "note": "圣母居中，国王和先知一圈圈围着她，光本身就是颜料。", "credit": "Wikimedia Commons, File:Chartres - cathédrale - rosace nord.jpg — 摄影 Eusebius，公有领域（作者声明）"}, {"img": "w4.webp", "w": 1200, "h": 1129, "who": "乔托", "whoLat": "Giotto di Bondone, c. 1267 – 1337", "title": "《哀悼基督》", "meta": ["约 1305 年，湿壁画", "200 × 185 cm", "帕多瓦，斯克罗维尼礼拜堂"], "note": "前景两个背影挡住视线，人物按空间摆放，不再按地位。", "credit": "Wikimedia Commons, File:Compianto sul Cristo morto.jpg — 摄影 Gennadii Saus i Segura，CC BY-SA 4.0（壁画本身属公有领域）"}], "chain": "之前：拜占庭圣像和罗马式教堂壁画，正面、金底、按等级排座次。契马布埃仍守着这套规矩，却已开始给宝座纵深、给脸加明暗。之后：几年后，乔托在帕多瓦把金底换成蓝天，让人物背对我们、在同一个空间里悲伤。下一厅的文艺复兴从这里开始。", "sources": [{"label": "乌菲齐美术馆 · 《圣三一圣母》", "claim": "《圣三一圣母》：约 1290–1300 年，木板蛋彩金底，384 × 223 cm，乌菲齐 Inv. 1890 n. 8343；原在佛罗伦萨圣三一教堂（瓦隆布罗萨会）；指路圣母姿势；八位天使；先知从左到右为耶利米、亚伯拉罕、大卫、以赛亚；年代“多有讨论”，倾向晚期", "url": "https://www.uffizi.it/en/artworks/virgin-and-child-enthroned-and-prophets-santa-trinita-maesta"}, {"label": "英文维基百科 · 圣三一圣母", "claim": "年代争议：部分学者定为 1280 年代，当代多定于阿西西壁画之后（1290–1300）；1471 年被移出主祭坛；1890 年修复时恢复尖顶", "url": "https://en.wikipedia.org/wiki/Santa_Trinita_Maest%C3%A0"}, {"label": "Smarthistory · 契马布埃《圣三一圣母》", "claim": "较早文献与教学材料定为约 1280–1290 年（Smarthistory）", "url": "https://smarthistory.org/cimabue-maesta/"}, {"label": "英文维基百科 · 契马布埃", "claim": "契马布埃：本名 Cenni di Pepo，约 1240 年生，1302 年卒；乌菲齐标注“有文献记载于 1272–1302 年”；瓦萨里所说收乔托为徒一事受学者质疑", "url": "https://en.wikipedia.org/wiki/Cimabue"}, {"label": "意大利文维基文库 · 《炼狱篇》第十一歌", "claim": "但丁《炼狱篇》第十一歌 94–96 行原文：Credette Cimabue ne la pittura / tener lo campo, e ora ha Giotto il grido, / sì che la fama di colui è scura", "url": "https://it.wikisource.org/wiki/Divina_Commedia/Purgatorio/Canto_XI"}, {"label": "英文维基百科 · 等级比例", "claim": "等级比例（hierarchical proportion）：以尺寸表示重要性，文艺复兴后被写实比例取代", "url": "https://en.wikipedia.org/wiki/Hierarchical_proportion"}, {"label": "牛津大学圣徒崇拜数据库 · 格里高利一世致塞雷努斯信", "claim": "格里高利一世约 600 年致马赛主教塞雷努斯信：图画为不识字者所读", "url": "https://portal.sds.ox.ac.uk/articles/online_resource/E06415_A_letter_of_Pope_Gregory_the_Great_Register_11_10_of_600_to_Serenus_bishop_of_Marseille_condemns_his_destruction_of_images_of_saints_in_Marseille_southern_Gaul_arguing_that_they_are_for_the_instruction_of_the_illiterate_Written_in_La/13902944"}, {"label": "英文维基百科 · 圣德尼修道院", "claim": "絮热重建圣德尼，唱诗堂 1144 年 6 月 11 日落成，追求“明亮窗户的连续之光”", "url": "https://en.wikipedia.org/wiki/Abbey_of_Saint-Denis"}, {"label": "英文维基百科 · 圣维塔莱教堂", "claim": "圣维塔莱教堂 547 年祝圣；查士丁尼与狄奥多拉镶嵌板 547 年完成；马克西米安主教名字为后加；查士丁尼戴金色光环居中，左右为军人与教士", "url": "https://en.wikipedia.org/wiki/Basilica_of_San_Vitale"}, {"label": "Smarthistory · 圣维塔莱教堂", "claim": "查士丁尼手持圣餐盘；查士丁尼与狄奥多拉本人从未到过拉文纳", "url": "https://smarthistory.org/san-vitale/"}, {"label": "都柏林圣三一学院图书馆 · 《凯尔经》", "claim": "《凯尔经》约 800 年，犊皮纸，340 叶，现约 330 × 255 mm（19 世纪重装时被裁切）；成于爱奥那或凯尔斯，不能确定", "url": "https://www.tcd.ie/library/research-collections/book-of-kells.php"}, {"label": "英文维基百科 · 凯尔经", "claim": "《凯尔经》Chi-Rho 页为第 34 页正面；馆藏编号 MS A. I. 58（今 MS 58）；纹样中藏有动物", "url": "https://en.wikipedia.org/wiki/Book_of_Kells"}, {"label": "英文维基百科 · 沙特尔主教座堂", "claim": "沙特尔北玫瑰窗约 1230 年（维基）/约 1235 年（WHE），直径 10.5 m，法兰西与卡斯蒂利亚纹章表明布朗歇王后赞助", "url": "https://en.wikipedia.org/wiki/Chartres_Cathedral"}, {"label": "世界历史百科 · 沙特尔的彩色玻璃窗", "claim": "北玫瑰窗约 1235 年，直径 10.5 m，中心圣母子，外圈犹大诸王与先知", "url": "https://www.worldhistory.org/article/1277/the-stained-glass-windows-of-chartres-cathedral/"}, {"label": "英文维基百科 · 乔托《哀悼基督》", "claim": "乔托《哀悼基督》约 1305 年，湿壁画，200 × 185 cm，帕多瓦斯克罗维尼礼拜堂", "url": "https://en.wikipedia.org/wiki/Lamentation_(The_Mourning_of_Christ)"}, {"label": "英文维基百科 · 斯克罗维尼礼拜堂", "claim": "斯克罗维尼礼拜堂壁画约 1303–1305 年，恩里科·斯克罗维尼委托", "url": "https://en.wikipedia.org/wiki/Scrovegni_Chapel"}, {"label": "乌菲齐美术馆 · 乔托《奥尼桑蒂圣母》", "claim": "乔托生卒（1267 Vespignano – 1337 Firenze），据乌菲齐相关作品条目", "url": "https://www.uffizi.it/en/artworks/virgin-and-child-enthroned-surrounded-by-angels-and-saints-ognissanti-maesta"}, {"label": "维基共享资源 · 主图文件页", "claim": "Commons 文件页：圣三一圣母扫描 2008 × 3596，来源 Google Arts & Culture，公有领域", "url": "https://commons.wikimedia.org/wiki/File:Cimabue_-_Maest%C3%A0_di_Santa_Trinita_-_Google_Art_Project.jpg"}, {"label": "维基共享资源 · 查士丁尼镶嵌图片文件页", "claim": "Commons 文件页：查士丁尼镶嵌照片，作者 Steven Zucker（Smarthistory），CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File:Justinian_mosaic,_San_Vitale,_consecrated_547,_Ravenna,_Italy.jpg"}, {"label": "维基共享资源 · 凯尔经图片文件页", "claim": "Commons 文件页：凯尔经 fol. 34r，PD-Art / PD-old-100", "url": "https://commons.wikimedia.org/wiki/File:KellsFol034rChiRhoMonogram.jpg"}, {"label": "维基共享资源 · 北玫瑰窗图片文件页", "claim": "Commons 文件页：沙特尔北玫瑰窗，Eusebius 2009 年摄，两张照片拼合，PD-self", "url": "https://commons.wikimedia.org/wiki/File:Chartres_-_cath%C3%A9drale_-_rosace_nord.jpg"}, {"label": "维基共享资源 · 哀悼基督图片文件页", "claim": "Commons 文件页：乔托《哀悼基督》，Gennadii Saus i Segura 2022 年摄，照片 CC BY-SA 4.0，壁画 PD-old-100-expired", "url": "https://commons.wikimedia.org/wiki/File:Compianto_sul_Cristo_morto.jpg"}, {"label": "都柏林圣三一学院 · 凯尔经 Chi-Rho 页的象征", "claim": "凯尔经 Chi-Rho 页（fol. 34r）纹样中的猫与老鼠（围着圣饼）、水獭与鱼、飞蛾", "url": "https://www.visittrinity.ie/blog/symbolism-in-the-book-of-kells-the-chi-rho-page/"}, {"label": "基督教经典电子图书馆 · 格里高利一世书信英译", "claim": "格里高利一世致塞雷努斯信（Register XI）英译：“文字之于读者，图画之于观看的无学者”", "url": "https://www.ccel.org/ccel/schaff/npnf213.ii.vii.iii.html"}]};

