(window.EH_ROOMS=window.EH_ROOMS||{})["renaissance"]={"id": "renaissance", "zh": "文艺复兴", "lat": "Renascentia", "yrs": "c. 1400 – 1520", "one": "人和神一样大，只差一指", "wall": "#A89E8E", "wallWhy": "墙面取西斯廷礼拜堂石灰华与灰泥在侧光下的暖灰色。原作本是一面湿壁画天顶，画在灰泥里，没有画框，四周是米开朗琪罗自己画的假建筑。墙色比画面的浅灰泥天空深两三档，淡色的底子才浮得出来；不用金色，因为这一厅要告别的正是中世纪的金底。", "ink": "dark", "frame": "none", "art": {"img": "main.webp", "w": 2400, "h": 1089, "who": "米开朗琪罗", "whoLat": "Michelangelo Buonarroti, 1475 – 1564", "title": "《创造亚当》", "meta": ["约 1511 年（旧说作 1510 年），湿壁画", "约 280 × 570 cm", "梵蒂冈城，梵蒂冈博物馆西斯廷礼拜堂天顶"], "credit": "Wikimedia Commons, File:Michelangelo - Creation of Adam (cropped).jpg — 公有领域（PD-Art）", "short": "《创造亚当》"}, "lede": "1508 年，一个自认是雕塑家的人被教皇派去画一整片天顶。他把人体画得和神一样重要。", "work": "亚当斜躺在光秃的山坡上，左臂伸向上帝，手腕无力，手指软软垂着。右边，上帝裹在一件鼓起的红斗篷里，由一群裸身的小天使托着飞来，右臂伸直，食指绷紧。两根手指之间留着一小段空白，整幅画的动势都停在这里。《创世记》说神照自己的形象造人，米开朗琪罗就让两者身量相当、面对面：亚当按真人的骨骼和肌肉画出。上帝左臂揽着的女子，常被解读为还未被造出的夏娃。", "quote": ["这个人像的美、姿态和轮廓，看上去像是最初、至高的造物主刚刚造出，而不是出自凡人的画笔和素描。", "瓦萨里《艺苑名人传·米开朗琪罗传》，1568 年版（据英译转述，非逐字）"], "origin": "14 世纪起，佛罗伦萨一带的人文学者搜求古希腊罗马的文本，想让古代学问重生，“文艺复兴”由此得名。15 世纪初，建筑师布鲁内莱斯基用一块画板和一面镜子演示，平行线在画面上会汇聚到一个灭点。到 1420 年代，马萨乔在《三位一体》里把这套方法画上教堂的墙；约 1435 年，阿尔贝蒂把它写进《论绘画》。1509–1511 年间，米开朗琪罗在西斯廷画天顶，拉斐尔在同一座梵蒂冈宫里画《雅典学院》，重心已从佛罗伦萨移到罗马。", "traits": [["身体有了骨骼和重量", "画家研究解剖和真人模特，让肌肉、关节和体重都有来处。米开朗琪罗年轻时获准在佛罗伦萨圣灵教堂的医院研究尸体，画人先想它怎样站、怎样用力。"], ["线性透视", "地砖、屋檐这类平行线在画里汇向同一个灭点，近大远小按几何算出来。平面后面打开一个像能走进去的空间，观者站在哪里也被算了进去。"], ["大小交给远近", "中世纪按神圣程度决定谁画得大。现在神、圣徒和凡人大多用同一套人体比例，谁大谁小看的是离观者多远，上帝也被画成一个有肌肉的老人。"], ["古代回来了", "拱券、壁柱、裸体和异教神话重新进入画面。波提切利画海上诞生的维纳斯，拉斐尔让古希腊哲学家聚在一座古罗马式大厅里，与教会题材并排。"]], "special": {"title": "差一指", "type": "reach", "text": "拖动亚当的手去够上帝，它总会弹回来，停在差一指的地方。这幅画常被读成这一刻：亚当的手指还软着，上帝的食指已经绷直，生命还没传过去。在约 5.7 米宽的画面上，两指只隔几厘米，中间什么也没画。画成碰上，事情就已经完成；留一道缝，画面停在“马上”之前，那一下由看的人自己补上。", "toggles": [{"key": "giornate", "label": "日工块", "text": "湿壁画要趁灰泥未干时上色，颜料随灰泥干透固定在墙里，所以画家每天只抹一块当天画得完的新灰泥，叫“日工块”（giornata）。接缝常贴着人物轮廓走。这里叠显的边界是示意，不是修复报告的实测图。据研究，亚当的轮廓是用尖笔刻进湿灰泥转上去的，上帝一组则主要用针孔扑粉。"}, {"key": "perspective", "label": "透视线", "text": "这组汇向两指之间的线是本展的设计，用来把目光领到那道缝上，不是米开朗琪罗的构图。天顶画没有统一的灭点。瓦萨里早就写过，他画这些格子不守透视规则，也没有固定视点，是让格子迁就人物。真正按一个灭点构图的，是本厅的《三位一体》和《雅典学院》。"}], "guides": {"note": "像素坐标以 main.webp（2400 × 1089）为准，原点左上；box 为 [x0, y0, x1, y1]", "adamTip": [905, 501], "godTip": [913, 492], "gapCenter": [909, 497], "gapPx": 12, "fingerWidthPx": 16, "adamHand": [745, 435, 905, 525], "godHand": [910, 440, 1100, 560], "adam": [12, 336, 1020, 1086], "godGroup": [1150, 24, 2400, 1050], "adamHead": [174, 336, 336, 480], "godHead": [1320, 156, 1458, 348], "adamShoulder": [396, 396]}}, "works": [{"img": "w1.webp", "w": 642, "h": 1200, "who": "马萨乔", "whoLat": "Masaccio (Tommaso di Ser Giovanni di Simone), 1401 – 1428", "title": "《三位一体》", "meta": ["约 1425–1428 年，湿壁画", "667 × 317 cm", "佛罗伦萨，新圣母大殿左侧廊"], "note": "现存最早系统使用线性透视的大型壁画之一。", "credit": "Wikimedia Commons, File:Masaccio - Trinity - Santa Maria Novella.jpg — 摄影 Oursana（推定），公有领域（PD-Art）"}, {"img": "w2.webp", "w": 1200, "h": 754, "who": "波提切利", "whoLat": "Sandro Botticelli, c. 1445 – 1510", "title": "《维纳斯的诞生》", "meta": ["约 1485 年，画布蛋彩", "172.5 × 278.5 cm", "佛罗伦萨，乌菲齐美术馆（Inv. 1890 n. 878）"], "note": "异教女神照古代雕像的姿势站上贝壳。", "credit": "Wikimedia Commons, File:Sandro Botticelli - La nascita di Venere - Google Art Project - edited.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, {"img": "w3.webp", "w": 805, "h": 1200, "who": "列奥纳多·达·芬奇", "whoLat": "Leonardo da Vinci, 1452 – 1519", "title": "《蒙娜丽莎》（丽莎·盖拉尔迪尼像）", "meta": ["1503–1519 年，杨木板油画", "79.4 × 53.4 cm", "巴黎，卢浮宫（INV 779）"], "note": "轮廓化进烟雾般的明暗，身后是无人的远景。", "credit": "Wikimedia Commons, File:Mona Lisa, by Leonardo da Vinci, from C2RMF retouched.jpg — 来源 C2RMF，公有领域（PD-Art）"}, {"img": "w4.webp", "w": 1200, "h": 784, "who": "拉斐尔", "whoLat": "Raphael (Raffaello Sanzio), 1483 – 1520", "title": "《雅典学院》", "meta": ["1509–1511 年，湿壁画", "约 500 × 770 cm", "梵蒂冈城，梵蒂冈博物馆拉斐尔厅·签字厅"], "note": "大厅的透视线汇向正中的柏拉图和亚里士多德。", "credit": "Wikimedia Commons, File:\"The School of Athens\" by Raffaello Sanzio da Urbino.jpg — 来源 vatican.va，公有领域（PD-Art）"}], "chain": "之前：乔托把人物放进同一个空间，马萨乔用一个灭点把空间算了出来；1506 年拉奥孔出土，米开朗琪罗被叫去现场，看到古人怎样雕刻扭转、用力的身体。之后：1536–1541 年他回到同一座礼拜堂，在祭坛墙上画《最后的审判》。", "sources": [{"label": "梵蒂冈博物馆 · 西斯廷礼拜堂的历史", "claim": "西斯廷天顶：1508 年尤利乌斯二世委托米开朗琪罗，1512 年 10 月完成；九幅《创世记》故事；1979–1999 年全面修复", "url": "https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/cappella-sistina/storia-cappella-sistina.html"}, {"label": "梵蒂冈博物馆 · 西斯廷天顶", "claim": "1508 年 5 月 8 日签约（原合同只画十二使徒和装饰）；1510 年 8 月完成前半部分；1512 年 10 月 31 日完工，11 月 1 日教皇主持弥撒", "url": "https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/cappella-sistina/volta.html"}, {"label": "梵蒂冈博物馆 · 《创造亚当》", "claim": "《创造亚当》馆方说明：手指接触传递生命气息；上帝由天使托着、裹在斗篷里；亚当如休息的运动员；《创世记》1:26–27", "url": "https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/cappella-sistina/volta/storie-centrali/creazione-di-adamo.html"}, {"label": "英文维基百科 · 创造亚当", "claim": "《创造亚当》280 × 570 cm，1508–1512；Meshberger 1990 年于 JAMA 提出上帝一组形似人脑（假说）；上帝左臂下的女性常被解读为夏娃（Walter Pater 等）", "url": "https://en.wikipedia.org/wiki/The_Creation_of_Adam"}, {"label": "意大利文维基百科 · 创造亚当", "claim": "《创造亚当》约 1511 年，天顶第二阶段；16 个日工块；上帝一组用扑粉（衣袍直接刻线）、亚当只用直接刻线转稿（本展只采用转稿方式一条，块数未写入墙签）", "url": "https://it.wikipedia.org/wiki/Creazione_di_Adamo"}, {"label": "网络艺术画廊（WGA）· 《创造亚当》", "claim": "旧定年 1510 年、280 × 570 cm（Web Gallery of Art）", "url": "https://www.wga.hu/html_m/m/michelan/3sistina/1genesis/6adam/index.html"}, {"label": "英文维基百科 · 西斯廷天顶画", "claim": "天顶：从入口一端画向祭坛；1510 年 9 月至 1511 年停工；《创造亚当》完成于 1511 年；湿壁画按日工块施工；1512 年 10 月 31 日揭幕", "url": "https://en.wikipedia.org/wiki/Sistine_Chapel_ceiling"}, {"label": "古登堡计划 · 瓦萨里《艺苑名人传》英译第 9 卷", "claim": "瓦萨里（De Vere 英译第 9 卷，1568 年版）：上帝由“一群年幼的裸身天使”托着；亚当“像是由最初、至高的造物主新近造出，而非凡人的画笔和素描”；天顶各格“不用透视规则、没有固定视点”，让格子迁就人物；圣灵教堂院长给他房间解剖尸体", "url": "https://www.gutenberg.org/files/32362/32362-h/32362-h.htm"}, {"label": "英文维基百科 · 米开朗琪罗", "claim": "米开朗琪罗 1475 年 3 月 6 日生于卡普雷塞，1564 年 2 月 18 日卒于罗马；圣灵教堂院长允许他研究医院尸体；不自认为画家", "url": "https://en.wikipedia.org/wiki/Michelangelo"}, {"label": "英文维基百科 · 西斯廷壁画修复", "claim": "修复：1980–1984 年先做弦月窗，天顶 1989 年 12 月完成；米开朗琪罗基本只用真湿壁画；日工块的完成度受温湿度影响", "url": "https://en.wikipedia.org/wiki/Restoration_of_the_Sistine_Chapel_frescoes"}, {"label": "英文维基百科 · 透视法", "claim": "阿尔贝蒂约 1435 年著《论绘画》；布鲁内莱斯基透视演示（画板、镜子、小孔）（仅作指引，年代见下条 webexhibits）", "url": "https://en.wikipedia.org/wiki/Perspective_(graphical)"}, {"label": "英文维基百科 · 马萨乔《三位一体》", "claim": "《三位一体》：en.wiki 作约 1426–1428 年、667 × 317 cm；最早的大型线性透视文艺复兴壁画之一；1570 年被瓦萨里的祭坛遮住，下部骷髅墓 1952 年归位（仅作指引，年代以下条馆方与本条合并为约 1425–1428 年）", "url": "https://en.wikipedia.org/wiki/Holy_Trinity_(Masaccio)"}, {"label": "乌菲齐美术馆 · 《维纳斯的诞生》", "claim": "《维纳斯的诞生》约 1485 年，画布蛋彩，172.5 × 278.5 cm，Inv. 1890 n. 878；波提切利 1445–1510；维纳斯姿势取自古代雕像", "url": "https://www.uffizi.it/en/artworks/birth-of-venus"}, {"label": "卢浮宫 · 《蒙娜丽莎》藏品页", "claim": "《蒙娜丽莎》（丽莎·盖拉尔迪尼像）1503–1519 年，杨木板油画，79.4 × 53.4 cm，INV 779；达·芬奇 1452–1519", "url": "https://collections.louvre.fr/en/ark:/53355/cl010062370"}, {"label": "梵蒂冈博物馆 · 《雅典学院》", "claim": "《雅典学院》：柏拉图持《蒂迈欧篇》指天、亚里士多德持《伦理学》；建筑取自布拉曼特的圣彼得设计；赫拉克利特为米开朗琪罗肖像；最右戴黑帽者为拉斐尔自画像；《雅典学院》与西斯廷天顶同时进行；柏拉图居中指天", "url": "https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/stanze-di-raffaello/stanza-della-segnatura/scuola-di-atene.html"}, {"label": "英文维基百科 · 雅典学院", "claim": "《雅典学院》1509–1511 年，湿壁画，500 × 770 cm；柏拉图与亚里士多德位于建筑的中心灭点", "url": "https://en.wikipedia.org/wiki/The_School_of_Athens"}, {"label": "英文维基百科 · 拉奥孔和他的儿子们", "claim": "1506 年拉奥孔出土，米开朗琪罗与朱利亚诺·达·桑加洛随即被叫到现场", "url": "https://en.wikipedia.org/wiki/Laoco%C3%B6n_and_His_Sons"}, {"label": "英文维基百科 · 最后的审判", "claim": "《最后的审判》1536–1541 年", "url": "https://en.wikipedia.org/wiki/The_Last_Judgment_(Michelangelo)"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图文件及许可：{{PD-Art|PD-old-auto-expired|deathyear=1564}}，约 1511 年，3524 × 1599，由 Creación de Adán.jpg 裁出（该页尺寸栏写 480.10 × 230.10 cm，与 WGA/it.wiki 的 280 × 570 cm 不符，未采用）", "url": "https://commons.wikimedia.org/wiki/File:Michelangelo_-_Creation_of_Adam_(cropped).jpg"}, {"label": "维基共享资源 · 三位一体图片文件页", "claim": "图片文件及许可：source 为 {{own assumed}} {{author assumed|Oursana}}，许可 {{PD-art|PD-old-100-expired}}", "url": "https://commons.wikimedia.org/wiki/File:Masaccio_-_Trinity_-_Santa_Maria_Novella.jpg"}, {"label": "维基共享资源 · 维纳斯的诞生图片文件页", "claim": "图片文件及许可：据 Google Art Project 原图调整色阶；PD-Art", "url": "https://commons.wikimedia.org/wiki/File:Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg"}, {"label": "维基共享资源 · 蒙娜丽莎图片文件页", "claim": "图片文件及许可：C2RMF 图像裁切、调色阶；{{PD-art|PD-old-100-expired}} + {{PD-retouched-user|Dcoetzee}}", "url": "https://commons.wikimedia.org/wiki/File:Mona_Lisa,_by_Leonardo_da_Vinci,_from_C2RMF_retouched.jpg"}, {"label": "维基共享资源 · 雅典学院图片文件页", "claim": "图片文件及许可：据 vatican.va 图像拼接，3820 × 2964；公有领域", "url": "https://commons.wikimedia.org/wiki/File:%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg"}, {"label": "新圣母大殿 · 马萨乔《三位一体》", "claim": "《三位一体》馆方：1425–1426 年；位于左侧中殿（侧廊）第三拱；1570 年被瓦萨里的祭坛遮住；1952 年修复时露出骷髅；“最早、最重要的文艺复兴透视范例之一”", "url": "https://www.smn.it/en/artworks/masaccios-holy-trinity/"}, {"label": "WebExhibits · 布鲁内莱斯基的透视实验", "claim": "布鲁内莱斯基透视演示的年代学界无定论：Gioseffi 1401–1409，Kemp 1413 年前，Edgerton 1425；方法据马内蒂记载为画板小孔加镜子", "url": "https://www.webexhibits.org/arrowintheeye/brunelleschi1.html"}, {"label": "华盛顿大学罗马课程页 · 拉奥孔出土记", "claim": "弗朗切斯科·达·桑加洛 1566 年回忆：1506 年拉奥孔出土，教皇派人叫朱利亚诺·达·桑加洛去看，正在他家的米开朗琪罗同去", "url": "http://courses.washington.edu/rome250/Michaelangelo%20Laocoon%20discovery.htm"}]};

