(window.EH_ROOMS=window.EH_ROOMS||{})["baroque"]={"id": "baroque", "zh": "巴洛克", "lat": "Barocco", "yrs": "c. 1600 – 1750", "one": "光照到谁，谁就被选中", "wall": "#1C1916", "wallWhy": "墙面取近黑的暖褐，比画里最暗的背景只亮一点，靠金框把两者分开。这一厅的主角是一道斜光，墙越暗，光越显眼，画外也像画里那间屋子一样黑。和中世纪厅的烛光褐相比，它更暗、更冷，因为这里的光不来自烛火，而来自一扇看不见的窗。", "ink": "light", "frame": "gilt", "art": {"img": "main.webp", "w": 2400, "h": 2267, "who": "卡拉瓦乔", "whoLat": "Caravaggio (Michelangelo Merisi), 1571 – 1610", "title": "《圣马太蒙召》", "short": "《圣马太蒙召》", "meta": ["1599–1600 年，布面油画", "322 × 340 cm", "罗马，法国圣路易堂孔塔雷利礼拜堂"], "credit": "Wikimedia Commons, File:Caravaggio — The Calling of Saint Matthew.jpg — 摄影 Gleb Simonov，CC0 1.0（画作本身属公有领域）"}, "lede": "1600 年，罗马一座教堂的侧礼拜堂里挂出一幅画：没有天国，只有一间暗屋、一桌数钱的人和一道斜光。", "work": "右边，基督和彼得刚走进一间昏暗的屋子。基督伸出右臂，手指朝向桌边；研究者早已指出，这只松软的手借自米开朗琪罗笔下的亚当，左右镜像。桌旁五个人穿着当时罗马的时髦衣服，有人戴羽毛帽，有人还低着头数桌上的钱。一道光从画框外的右上方斜射进来，擦过基督的手，落在几张抬起的脸上。墙上那扇窗关着，并不是光的来处。", "quote": ["这一派的特点，是用一束从高处来、没有反光的统一的光，就像屋里只有一扇窗、墙壁涂成黑色；亮处极亮，暗处极暗，画就凸了出来……", "朱利奥·曼奇尼《关于绘画的思考》，约 1617–1621 年（本展据意大利文译）"], "origin": "为回应宗教改革，天主教会在特伦托大公会议（1545–1563 年）之后要求宗教艺术直接诉诸情感和感官，让普通信众一看就懂。罗马是这场运动的中心。1599 年，德尔蒙特枢机替住在他府上的卡拉瓦乔争取到第一份教堂委托：按已故的孔塔雷利枢机的遗愿，画圣马太的故事。1600 年两幅侧壁画揭幕，他一举成名，仿效者遍及欧洲。“巴洛克”一说本指形状不规则的珍珠，后来成了批评家贬斥离经叛道之作的词；直到 1888 年沃尔夫林出书，它才成为中性的风格名。", "traits": [["明暗对照", "画面大半沉在黑暗里，只有一束强光照亮要紧的脸、手和动作。卡拉瓦乔把明暗的反差推到极端，从罗马到乌得勒支、那不勒斯，整整一代画家跟着学。"], ["停在最紧张的一刻", "巴洛克画家爱挑故事里最戏剧化的一瞬：被召唤、被刺中、被击倒的那一下。动作做到一半，人物斜着向画外冲来，像舞台上的灯刚刚打亮。"], ["圣徒穿今天的衣服", "卡拉瓦乔照着真人模特画，让使徒赤着脏脚、穿着旧衣，让马太坐在一桌时髦的罗马人中间。一千五百多年前的故事，像就发生在观者自己的街上。"], ["各门艺术合成一场戏", "建筑、雕塑、绘画的界限变得模糊：教堂天顶画成敞开的天空，雕像配上真实的光线和彩色石料。观者不再只是站在画前，而是被整个场景包围。"]], "special": {"title": "光落在谁身上", "type": "calling", "text": "拖动右上角的“窗”，改变光射进来的角度：光照到谁，谁就被召唤。松手后，光回到卡拉瓦乔定下的方向。据研究，这道光与孔塔雷利礼拜堂正中那扇窗的来光同向，挂在墙上的画就像被礼拜堂真实的窗照亮。卡拉瓦乔用光指明谁被选中，可光究竟停在谁身上，看画的人至今意见不一。", "choice": {"q": "谁是马太？", "options": [{"key": "bearded", "label": "指着自己的大胡子", "text": "多数研究者认为是他。他抬头望着基督，一只手指向自己，像在问“我？”。从 17 世纪的贝洛里起，人们大多这样读；同一礼拜堂另外两幅画里的马太，也是一个相似的大胡子。"}, {"key": "youth", "label": "桌尾数钱的年轻人", "text": "1985 年，德国学者普拉特提出马太是桌尾那个年轻人：他还低着头数钱，没有看见基督。照这个读法，大胡子的手指指的是身边的他，画停在马太抬头之前。福音书里基督说自己“本不是召义人，乃是召罪人”，也被拿来支持这一说。"}], "note": "两种读法至今都有人坚持，本展不作裁决。"}, "guides": {"note": "像素坐标以 main.webp（2400 × 2267）为准，原点左上；box 为 [x0, y0, x1, y1]；目测，误差约 ±20 px", "christHand": [1545, 895, 1710, 1000], "christFingertip": [1555, 938], "christSleeve": [1700, 895, 1810, 1000], "christHead": [2010, 790, 2160, 960], "christHalo": [2050, 690, 2200, 760], "peterHead": [1810, 830, 2010, 1010], "peterHand": [1750, 1140, 1880, 1215], "christPeterGroup": [1540, 690, 2400, 2267], "paintedWindow": [1200, 0, 1935, 765], "shadowEdge": {"from": [2400, 642], "to": [1450, 904], "note": "后墙上亮区与右下暗楔的分界线，斜率约 0.276（约 15°）；线的左上方是被照亮的墙"}, "beamAxis": {"from": [2400, 250], "to": [780, 1060], "note": "估计的主光方向（约 27° 向左下），不是实测；光源在画框外右上方"}, "table": [150, 1380, 1250, 1560], "coins": [630, 1450, 720, 1495], "matthewBearded": {"head": [690, 940, 845, 1155], "face": [730, 990, 830, 1100], "hand": [740, 1170, 900, 1250]}, "youthCounting": {"head": [440, 1110, 625, 1325], "face": [505, 1255, 590, 1315], "countingHand": [530, 1380, 645, 1480], "body": [150, 1110, 700, 1560]}, "oldManSpectacles": {"head": [440, 920, 565, 1085], "spectacles": [495, 1025, 545, 1050]}, "boyFeatherHat": {"head": [950, 900, 1185, 1135], "face": [990, 1010, 1100, 1120]}, "youthOnStool": {"head": [1430, 1030, 1565, 1250], "face": [1440, 1150, 1510, 1240], "body": [1280, 1030, 1570, 2050]}}}, "works": [{"img": "w1.webp", "w": 972, "h": 1200, "who": "阿尔泰米西娅·真蒂莱斯基", "whoLat": "Artemisia Gentileschi, 1593 – 1652/53", "title": "《朱迪斯斩杀荷罗孚尼》", "meta": ["约 1620 年，布面油画", "146.5 × 108 cm", "佛罗伦萨，乌菲齐美术馆（Inv. 1890 n. 1567）"], "note": "卡拉瓦乔式的强光打在床上，两个女人合力按住敌将。", "credit": "Wikimedia Commons, File:Artemisia Gentileschi - Giuditta decapita Oloferne - Google Art Project.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, {"img": "w2.webp", "w": 1200, "h": 976, "who": "伦勃朗", "whoLat": "Rembrandt van Rijn, 1606 – 1669", "title": "《夜巡》", "meta": ["1642 年，布面油画", "379.5 × 453.5 cm", "阿姆斯特丹，荷兰国立博物馆（SK-C-5）"], "note": "民兵正在列队出发，光挑出队长的手和一个小女孩。", "credit": "Wikimedia Commons, File:The Nightwatch by Rembrandt - Rijksmuseum.jpg — 来源 Rijksmuseum，公有领域（PD-Art）"}, {"img": "w3.webp", "w": 900, "h": 1200, "who": "贝尼尼", "whoLat": "Gian Lorenzo Bernini, 1598 – 1680", "title": "《圣特雷莎的狂喜》", "meta": ["1647–1652 年，大理石，镀金铜光束", "人物与真人等大", "罗马，胜利圣母堂科尔纳罗礼拜堂"], "note": "上方暗藏一扇窗，天光顺着金色光束落在圣女身上。", "credit": "Wikimedia Commons, File:Ecstasy of Saint Teresa.JPG — 摄影 Sumselkawumsel，CC BY-SA 3.0（雕塑本身属公有领域）"}, {"img": "w4.webp", "w": 1043, "h": 1200, "who": "委拉斯开兹", "whoLat": "Diego Velázquez, 1599 – 1660", "title": "《宫娥》", "meta": ["1656 年，布面油画", "320.3 × 279.1 cm", "马德里，普拉多博物馆（P001174）"], "note": "光从右侧窗口和后门照进宫殿，镜中映出国王夫妇。", "credit": "Wikimedia Commons, File:Las Meninas, by Diego Velázquez, from Prado in Google Earth.jpg — 来源 Museo del Prado / Google Earth，公有领域（PD-Art）"}], "chain": "之前：米开朗琪罗和拉斐尔之后，罗马流行优雅而程式化的样式主义；卡拉瓦乔改从真人画起，拿光来讲故事。之后：他的画法经追随者传遍欧洲，伦勃朗、委拉斯开兹都受其影响；18 世纪初，巴黎的室内装饰反过来追求轻快柔和，这就是下一厅的洛可可。", "sources": [{"label": "英文维基百科 · 圣马太蒙召", "claim": "《圣马太蒙召》1599–1600 年，布面油画，322 × 340 cm（高 × 宽），罗马法国圣路易堂孔塔雷利礼拜堂；两幅侧壁画 1599 年 7 月委托、1600 年 7 月结款；马太身份两说（Lavin 1993 主大胡子，Hass 1988 主年轻人）；基督手势与西斯廷亚当的手相应（Lavin 1993，第 95 页）", "url": "https://en.wikipedia.org/wiki/The_Calling_of_Saint_Matthew"}, {"label": "英文维基百科 · 孔塔雷利礼拜堂", "claim": "孔塔雷利（Cointrel）枢机 1585 年去世，留下装饰礼拜堂的遗赠；1599 年 7 月 23 日签约，卡拉瓦乔第一份大型公共委托；《蒙召》在左墙；两幅侧壁画都由礼拜堂唯一的自然光源方向的光照亮", "url": "https://en.wikipedia.org/wiki/Contarelli_Chapel"}, {"label": "英文维基百科 · 孔塔雷利礼拜堂的画", "claim": "《蒙召》在左墙，光来自右上方；《殉难》光向相反；一切安排都让人觉得是礼拜堂正中那扇窗在照亮画面，尽管它透光很少（引 Jaubert 1998、Moir 1994）；马太的模特在三幅画中逐幅变老", "url": "https://en.wikipedia.org/wiki/Paintings_in_the_Contarelli_Chapel"}, {"label": "大都会艺术博物馆 · 卡拉瓦乔及其追随者（Keith Christiansen，2003）", "claim": "卡拉瓦乔 1571–1610；德尔蒙特枢机让他住进府邸，并为他争取到第一份教堂委托；两幅马太画 1600 年揭幕并奠定声誉；穿当时服装；卡拉瓦乔画派传遍欧洲（乌得勒支画家、法国与西班牙画家）；引同时代批评家论“一扇窗、墙壁涂黑”的光", "url": "https://www.metmuseum.org/essays/caravaggio-michelangelo-merisi-1571-1610-and-his-followers"}, {"label": "意大利文维基语录 · 朱利奥·曼奇尼", "claim": "曼奇尼《关于绘画的思考》（Considerazioni sulla pittura，约 1617–1621 年）原文：“Proprio di questa schola è di lumeggiar con lume unito che venghi d'alto senza reflessi, come sarebbe in una stanza da una fenestra con le pariete colorite di negro, che così, havendo i chiari e l'ombre molto chiare e molto oscure, vengono a dar rilievo alla pittura [...]”（本展据此中译）", "url": "https://it.wikiquote.org/wiki/Giulio_Mancini"}, {"label": "Kunstgeschichte 开放期刊 · Jürgen Müller《谁是马太？》（2021）", "claim": "Prater 1985 年首先提出数钱的年轻人是马太，此后争论不断；Hass 1988、Careri 等从之，Pericolo、Schütze、Ebert-Schifferer 主大胡子；多数研究者仍从贝洛里，读作大胡子（注 37）；以《马太福音》9:13“召罪人”支持年轻人说；Friedlaender 1955 指出引用米开朗琪罗《创造亚当》，Wagner 1958、Hibbard 1983 确认引用的是亚当无力的手；画中窗户是“盲窗”，光来自右侧画框外；X 光显示基督原为单独一人，彼得后加", "url": "https://www.kunstgeschichte-ejournal.net/577/"}, {"label": "大英百科全书 · 巴洛克艺术与建筑", "claim": "巴洛克大致对应 17 世纪；词源可能来自中世纪逻辑术语 barocco，另一可能来源是葡萄牙语 barroco（不规则珍珠）；长期带贬义，1888 年沃尔夫林《文艺复兴与巴洛克》后成为风格名；特伦托大公会议（1545–1563）后教会要求艺术公开诉诸情感和感官；样式主义已不敷用；各门艺术界限模糊", "url": "https://www.britannica.com/art/Baroque-art-and-architecture"}, {"label": "大英百科全书 · 卡拉瓦乔（Andrew Graham-Dixon）", "claim": "卡拉瓦乔 1571 年 9 月 29 日生，1610 年 7 月 18/19 日卒于埃尔科莱港；以真人为模特、穿当代服装；强调使徒的破衣和脏脚；极端明暗对照；影响伦勃朗、委拉斯开兹", "url": "https://www.britannica.com/biography/Caravaggio"}, {"label": "大英百科全书 · 洛可可", "claim": "洛可可 18 世纪初起源于巴黎室内装饰，特点是轻快、优雅；最初是对路易十四凡尔赛宫厚重设计与官方巴洛克的反动", "url": "https://www.britannica.com/art/Rococo"}, {"label": "维基文库 · 圣经（和合本）马太福音", "claim": "《马太福音》9:9 马太在税关上蒙召；9:13“我来本不是召义人，乃是召罪人”（和合本）", "url": "https://zh.wikisource.org/zh-hans/%E8%81%96%E7%B6%93_(%E5%92%8C%E5%90%88%E6%9C%AC)/%E9%A6%AC%E5%A4%AA%E7%A6%8F%E9%9F%B3"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图：Gleb Simonov（Gsimonov）2024 年 1 月 18 日自摄，CC0 1.0，原图 8792 × 8304（该页尺寸栏把高宽写反、日期写作 1609 年 7 月，均未采用）", "url": "https://commons.wikimedia.org/wiki/File:Caravaggio_%E2%80%94_The_Calling_of_Saint_Matthew.jpg"}, {"label": "乌菲齐美术馆 · 《朱迪斯斩杀荷罗孚尼》", "claim": "约 1620 年，布面油画，146.5 × 108 cm，Inv. 1890 n. 1567；阿尔泰米西娅 1593 年生于罗马，1652/53 年卒于那不勒斯；科西莫二世委托；受卡拉瓦乔自然主义影响", "url": "https://www.uffizi.it/en/artworks/judith-beheading-holofernes"}, {"label": "维基共享资源 · 朱迪斯图片文件页", "claim": "图片来自 Google Cultural Institute，{{PD-Art|PD-old-100-1923}}；该页尺寸栏 199 × 162.5 cm 与馆方不符，未采用", "url": "https://commons.wikimedia.org/wiki/File:Artemisia_Gentileschi_-_Giuditta_decapita_Oloferne_-_Google_Art_Project.jpg"}, {"label": "荷兰国立博物馆 · 《夜巡》", "claim": "1642 年，布面油画，379.5 × 453.5 cm，SK-C-5；伦勃朗用光突出队长的手势和小女孩；群像中的人物正在列队行动", "url": "https://www.rijksmuseum.nl/en/collection/SK-C-5"}, {"label": "英文维基百科 · 伦勃朗", "claim": "伦勃朗 1606–1669", "url": "https://en.wikipedia.org/wiki/Rembrandt"}, {"label": "维基共享资源 · 夜巡图片文件页", "claim": "Rijksmuseum 提供的全幅图像，公有领域", "url": "https://commons.wikimedia.org/wiki/File:The_Nightwatch_by_Rembrandt_-_Rijksmuseum.jpg"}, {"label": "英文维基百科 · 圣特雷莎的狂喜", "claim": "1647–1652 年，白色大理石群像，真人大小，罗马胜利圣母堂科尔纳罗礼拜堂，费德里科·科尔纳罗枢机委托；光从神龛顶部暗藏的窗射入，配镀金光束；两侧科尔纳罗家族像如在剧院包厢观看", "url": "https://en.wikipedia.org/wiki/Ecstasy_of_Saint_Teresa"}, {"label": "大英百科全书 · 圣特雷莎的狂喜", "claim": "大理石与镀金铜的壁龛雕塑，1645–52 年，罗马胜利圣母堂科尔纳罗礼拜堂", "url": "https://www.britannica.com/topic/The-Ecstasy-of-Saint-Teresa"}, {"label": "Artribune · 科尔纳罗礼拜堂修复完成（2021）", "claim": "修复报道：“i raggi in bronzo dorato”（镀金铜光束）；贝尼尼造了一间“光室”，阳光经黄色和琥珀色玻璃滤入；1647 年费德里科·科尔纳罗枢机取得礼拜堂", "url": "https://www.artribune.com/arti-visive/archeologia-arte-antica/2021/10/restauro-cappella-cornaro-estasi-santa-teresa-bernini/"}, {"label": "英文维基百科 · 贝尼尼", "claim": "贝尼尼 1598–1680", "url": "https://en.wikipedia.org/wiki/Gian_Lorenzo_Bernini"}, {"label": "维基共享资源 · 圣特雷莎图片文件页", "claim": "Sumselkawumsel 2012 年自摄，CC BY-SA 3.0 / GFDL", "url": "https://commons.wikimedia.org/wiki/File:Ecstasy_of_Saint_Teresa.JPG"}, {"label": "普拉多博物馆 · 《宫娥》", "claim": "1656 年，布面油画，高 320.3 cm、宽 279.1 cm，P001174；委拉斯开兹 1599 年生于塞维利亚，1660 年卒于马德里；镜中映出腓力四世与玛丽安娜；多重光源塑造空间", "url": "https://www.museodelprado.es/en/the-collection/art-work/las-meninas/9fdc7800-9ade-48b0-ab8b-edee94ea877f"}, {"label": "英文维基百科 · 宫娥", "claim": "光有两个来源：敞开的后门和右侧窗户", "url": "https://en.wikipedia.org/wiki/Las_Meninas"}, {"label": "维基共享资源 · 宫娥图片文件页", "claim": "来自普拉多博物馆 Google Earth 图层，公有领域（该页尺寸 318 × 276 cm 为旧数据，以馆方为准）", "url": "https://commons.wikimedia.org/wiki/File:Las_Meninas,_by_Diego_Vel%C3%A1zquez,_from_Prado_in_Google_Earth.jpg"}, {"label": "Stork & Nagy · 用计算机图形推断《圣马太蒙召》的布光", "claim": "右上角向上斜的投影边线；光源位于画框外右侧（仅供转场设计参考，未写入墙签）", "url": "https://diatrope.com/stork/StorkNagy.pdf"}]};

;
(window.EH_ROOMS=window.EH_ROOMS||{})["rococo"]={"id": "rococo", "zh": "洛可可", "lat": "Rococo", "yrs": "c. 1720 – 1780", "one": "直线弯成曲线，庄重换成调情", "wall": "#C9D1C3", "wallWhy": "墙面取巴黎贵族小客厅护墙板常用的淡彩，这里选浅灰绿：底子清淡，金色涡卷在上面游走。《秋千》本身是一片深绿的树林，只有粉裙最亮；挂在浅墙上，它像一扇开向林子的窗。画框用金色，四角可以卷成不对称的贝壳涡卷。从巴洛克的暗处走出来，这一厅是白天的花园。", "ink": "dark", "frame": "gilt", "art": {"img": "main.webp", "w": 1912, "h": 2400, "who": "弗拉戈纳尔", "whoLat": "Jean-Honoré Fragonard, 1732 – 1806", "title": "《秋千》", "short": "《秋千》", "meta": ["约 1767–1768 年，布面油画", "81 × 64.2 cm", "伦敦，华莱士收藏馆（P430）"], "credit": "Wikimedia Commons, File:Fragonard, The Swing.jpg — 来源 华莱士收藏馆指南（Oxford Art Online），公有领域（PD-Art）"}, "lede": "画从教堂的祭坛和宫廷的大厅，搬进了私人的小客厅。尺寸变小，颜色变淡，题目只剩下取乐。", "work": "林间空地上，一位穿粉色丝裙的年轻女子高高荡起，一只脚踢出去，粉色便鞋飞到了半空。左下方，一个年轻人半躺在花丛里，举着帽子，正好从裙下往上看。右边的阴影里，一位年长的男人拉着绳子把秋千送出去，脚边一只小白狗在叫。左侧石座上的丘比特把手指按在唇边，像在叫人别声张。光从左上方的云隙落下来，照亮粉裙，四周的树林都沉在深绿里。", "quote": ["我不知道该拿这个人怎么说。趣味、色彩、构图、人物、表情、素描的堕落，一步一步跟着风俗的败坏走。", "狄德罗《1765 年沙龙》评布歇（本展译）"], "origin": "1715 年路易十四去世，摄政王把宫廷从凡尔赛搬回巴黎，贵族在城里盖起私宅，沙龙里的规矩也松了下来。房间变小，墙面换成白底描金的木护墙板，装饰借用岩洞里的贝壳和卵石，叫作“岩饰”（rocaille）。1735–1740 年间，建筑师博夫朗在苏比斯府做出了其中的代表作。风格从巴黎传到德意志的宫殿和教堂。1750 年代起，批评家嫌它轻浮做作；到 1780 年代，新古典主义占了上风。“洛可可”这个词出现得更晚，是后来讥讽旧式装饰时造的。", "traits": [["C 形和 S 形", "画框、护墙板、桌椅的腿都弯成 C 形和 S 形的涡卷，左右故意不对称。直角被藏起来，墙和天花板之间也用弧面接过去，整间屋子像在流动。"], ["粉彩和空气", "巴洛克的深褐底色退场，换成粉红、天蓝、象牙白和浅绿，再点上金色。阴影很少压到全黑，人物像浮在一层发亮的空气里。"], ["画给小房间", "主顾里多了银行家、包税人和贵妇。画多是挂在私人客厅、卧室里的小幅作品，不必教化谁，只要好看、讨喜，最好还藏一点只有主人懂的玩笑。"], ["爱情是一场游戏", "题材多是恋人在花园里游乐、牧羊人的田园梦和维纳斯的神话。调情写得明明白白，又用一尊雕像、一只小狗、一只鞋把话说得含蓄，留给看画的人会心一笑。"]], "special": {"title": "你来拉绳", "type": "swing", "text": "你站在右边阴影里那位老先生的位置。秋千荡回来时拉一把，节奏对了，一次比一次高。这正是画里分给他的活：他的位置看不到裙下，只负责把她送出去，好让年轻人看见。两个男人的手势和目光都朝着她，她自己却把鞋踢飞了。秋千停在画里的原位，鞋还在半空，谁也没接住。", "hint": {"mouse": "秋千荡回来时往下拖，或按住“拉绳”；荡得够高，鞋会飞出来，可以接住再扔。单击年轻人、老先生或丘比特，听这幅画是怎么订出来的。", "touch": "秋千荡回来时向下拖；荡得够高，鞋会飞出来，可以接住再扔。轻触年轻人、老先生或丘比特，听这幅画是怎么订出来的。"}, "stories": {"youngman": "据剧作家科莱 1767 年 10 月的日记，一位宫廷贵人要求把自己也画进去，放在“看得见这漂亮姑娘双腿”的地方。科莱没写他是谁，通常认为是教会收税官圣朱利安。", "oldman": "据科莱记载，委托人原本要一位主教来推秋千。历史画家多扬大吃一惊，推掉了这单，转荐弗拉戈纳尔。成画里推秋千的是一位俗人，华莱士收藏馆称他为年长的丈夫。", "cupid": "左边这尊丘比特，照的是法尔科内为蓬巴杜夫人雕的《威胁的爱神》，1757 年展出，现藏卢浮宫。科莱记下的要求里没有它，像是画家自己加的旁白：嘘，别说出去。"}, "guides": {"note": "像素坐标以 main.webp（1912 × 2400）为准，原点左上；box 为 [x0, y0, x1, y1]，约 ±15 px，详见 notes.md", "woman": [500, 1225, 1290, 1850], "womanHead": [985, 1225, 1165, 1375], "flyingShoe": [420, 1265, 485, 1335], "bareFoot": [495, 1395, 590, 1465], "seat": [895, 1600, 1005, 1705], "ropeAnchor": [1265, 615], "youngman": [130, 1790, 610, 2175], "youngmanHat": [555, 1745, 635, 1835], "oldman": [1380, 1675, 1710, 2200], "oldmanHands": [[1390, 1785], [1505, 1855]], "cupid": [0, 1085, 215, 1530], "cupidPedestal": [0, 1525, 280, 1725], "putti": [1005, 1740, 1300, 2010], "dog": [1440, 2165, 1520, 2260]}}, "works": [{"img": "w1.webp", "w": 1200, "h": 787, "who": "华托", "whoLat": "Jean-Antoine Watteau, 1684 – 1721", "title": "《舟发西苔岛》", "meta": ["1717 年，布面油画", "129 × 194 cm", "巴黎，卢浮宫（INV 8525）"], "note": "学院登记时把它写成一幅“雅宴”，画种由此得名。", "credit": "Wikimedia Commons, File:L'Embarquement pour Cythère, by Antoine Watteau, from C2RMF retouched.jpg — 来源 C2RMF，公有领域（PD-Art）"}, {"img": "w2.webp", "w": 896, "h": 1200, "who": "博夫朗、纳图瓦尔等", "whoLat": "Germain Boffrand, 1667 – 1754; Charles-Joseph Natoire, 1700 – 1777", "title": "《苏比斯府公主沙龙》", "meta": ["1735–1740 年，木雕贴金、镜面与布面油画", "尺寸不详", "巴黎，苏比斯府（今法国国家档案馆博物馆）"], "note": "椭圆的房间，白墙金线，找不到一个直角。", "credit": "Wikimedia Commons, File:Salon ovale de la princesse in the Hôtel de Soubise (11).jpg — 摄影 Neoclassicism Enthusiast，CC BY-SA 4.0"}, {"img": "w3.webp", "w": 1200, "h": 924, "who": "贺加斯", "whoLat": "William Hogarth, 1697 – 1764", "title": "《美的分析》（图版一）", "meta": ["1753 年，蚀刻与雕版（第三状态）", "38.8 × 50 cm（纸张）", "纽约，大都会艺术博物馆（32.35(22)）"], "note": "第 49 图排着七条波浪线，他说第 4 条最美。", "credit": "Wikimedia Commons, File:The Analysis of Beauty, Plate 1 MET DP827041.jpg — 来源 The Metropolitan Museum of Art，CC0"}, {"img": "w4.webp", "w": 936, "h": 1200, "who": "布歇", "whoLat": "François Boucher, 1703 – 1770", "title": "《蓬巴杜夫人像》", "meta": ["1756 年，布面油画", "205 × 161 cm", "慕尼黑，老绘画陈列馆（HUW 18）"], "note": "国王的情妇被书信和乐谱围着，要人看见她的学识。", "credit": "Wikimedia Commons, File:Madame de Pompadour.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}], "chain": "之前：巴洛克用硬光和大场面讲信仰与王权，凡尔赛的大厅对称而厚重。之后：1785 年沙龙上，大卫的《荷拉斯兄弟之誓》让直线、硬光和牺牲重新回到画里；大革命后弗拉戈纳尔失去主顾，1806 年在巴黎去世，身后几十年少有人提起。", "sources": [{"label": "华莱士收藏馆 · 藏品页《秋千》", "claim": "《秋千》（Les hasards heureux de l'escarpolette）约 1767–1768 年，81 × 64.2 cm，P430；粉色丝裙女子、一侧年长的丈夫、一侧年轻恋人；鞋掉落、年轻人递帽", "url": "https://www.wallacecollection.org/explore/collection/search-the-collection/les-hazards-heureux-de-lescarpolette-swing/"}, {"label": "华莱士收藏馆在线图录 · The Swing", "claim": "布面油画，画心 81 × 64.2 cm，P430；据科莱日记，1767 年末宫廷贵人先请多扬画情妇荡秋千，多扬推荐弗拉戈纳尔；成画与原要求不同：老人不再是主教，添了狗，法尔科内的《威胁的爱神》像在评点；标题出自德洛奈 1782 年版画", "url": "https://wallacelive.wallacecollection.org/eMP/eMuseumPlus?service=ExternalInterface&module=collection&objectId=65364&viewType=detailView"}, {"label": "华莱士收藏馆 · 《秋千》的委托", "claim": "科莱 1767 年 10 月记：贵人要画“夫人坐在一位主教推动的秋千上”，并把自己放在“看得见这漂亮姑娘双腿”的位置；多扬觉得震惊而推辞；委托人未具名，长期被认为是法国教会的包税人圣朱利安（François-David Bollioud de Saint-Julien）", "url": "https://www.wallacecollection.org/explore/explore-in-depth/fragonards-the-swing/origins-of-the-swing/the-commission/"}, {"label": "法文维基百科 · 秋千的美妙机缘", "claim": "科莱原文“sur une escarpolette qu'un évêque mettrait en branle … à portée de voir les jambes de cette belle enfant”，出处 Collé《Journal et mémoires》第 3 卷（Firmin Didot，1868），第 165–166 页，1767 年 10 月", "url": "https://fr.wikipedia.org/wiki/Les_Hasards_heureux_de_l%27escarpolette"}, {"label": "英文维基百科 · 秋千（弗拉戈纳尔）", "claim": "剧作家科莱回忆录：宫廷贵人先请多扬画主教推秋千，多扬推荐弗拉戈纳尔，后者画成俗人；女子踢飞鞋、年轻人藏在花丛、老人在阴影里拉绳、小白狗在叫、竖指贴唇的丘比特像；2021 年修复", "url": "https://en.wikipedia.org/wiki/The_Swing_(Fragonard)"}, {"label": "The Art Newspaper · 修复后的《秋千》", "claim": "2021 年马丁·怀尔德清洗修复；推秋千的老人衣服是蓝色而非黑色，不像主教；策展人贾卡尔推测这是“三角恋”，老人是年长的丈夫；也可能老人与年轻人是父子", "url": "https://www.theartnewspaper.com/2021/10/28/fragonards-the-swing-has-been-restoredand-its-saucier-than-ever"}, {"label": "卢浮宫 · 法尔科内《威胁的爱神》", "claim": "法尔科内（1716–1791）《威胁的爱神》，蓬巴杜夫人订制，石膏稿 1755 年沙龙、大理石 1757 年沙龙展出；1761 年在埃夫勒府花园；1877 年遗赠、1879 年入藏卢浮宫（RF 296）", "url": "https://collections.louvre.fr/en/ark:/53355/cl010092907"}, {"label": "大英百科全书 · 弗拉戈纳尔", "claim": "弗拉戈纳尔 1732 年 4 月 5 日生于格拉斯，1806 年 8 月 22 日卒于巴黎；1752 年参加罗马奖；大革命使他失去私人主顾，晚年默默无闻，去世几乎无人注意，直到 1850 年后才重新受重视", "url": "https://www.britannica.com/biography/Jean-Honore-Fragonard"}, {"label": "Utpictura18 · 狄德罗《1765 年沙龙》论布歇", "claim": "狄德罗 1765 年沙龙评布歇原文：“Je ne sais que dire de cet homme. La dégradation du goût, de la couleur, de la composition, du caractère, de l'expression, du dessin, a suivi pas à pas la dépravation des mœurs.”", "url": "https://utpictura18.univ-amu.fr/en/rubriques/numeros/salons-diderot-edition/boucher-salon-of-1765"}, {"label": "英文维基百科 · 摄政时期", "claim": "1715–1723 年摄政时期，宫廷由凡尔赛迁往巴黎，1722 年回到凡尔赛；巴黎沙龙里贵族与上层市民交往，礼数放松；装饰风格走向洛可可", "url": "https://en.wikipedia.org/wiki/R%C3%A9gence"}, {"label": "凡尔赛宫 · 1722 年宫廷迁回凡尔赛", "claim": "路易十四 1715 年去世后，幼王先住万塞讷、再住巴黎杜伊勒里宫；1722 年 6 月 15 日宫廷回到凡尔赛", "url": "https://en.chateauversailles.fr/discover/history/key-dates/court-returns-versailles-1722"}, {"label": "英文维基百科 · 洛可可", "claim": "“洛可可”由 rocaille（岩饰：用贝壳卵石装饰岩洞）而来，据说由新古典画家奎斯（1777–1803）戏称，约 1825 年见于印刷品且带贬义；1730 年代在巴黎兴起；曲线、不对称、粉彩配金；苏比斯府（博夫朗、纳图瓦尔，1735–1740）；传入德意志；1750–1760 年代遭批评，1780 年代被新古典主义取代", "url": "https://en.wikipedia.org/wiki/Rococo"}, {"label": "大英百科全书 · 洛可可", "claim": "名称来自 rocaille（装饰人造岩洞的贝壳岩饰）；18 世纪初起于巴黎贵族新宅，浅粉彩、象牙白配金，不对称；1730 年代传入德语天主教地区；1750 年代在法国受批评，1760 年代起新古典主义逐步取代", "url": "https://www.britannica.com/art/Rococo"}, {"label": "卢浮宫 · 华托《舟发西苔岛》", "claim": "《西苔岛朝圣》（又名《舟发西苔岛》）1717 年，布面油画，129 × 194 cm，INV 8525；华托（1684–1721）的皇家学院入选作；开创“雅宴画”", "url": "https://collections.louvre.fr/en/ark:/53355/cl010061995"}, {"label": "英文维基百科 · 舟发西苔岛", "claim": "1717 年入选作，学院为它新设了一个类别，即“雅宴画”", "url": "https://en.wikipedia.org/wiki/Pilgrimage_to_Cythera"}, {"label": "英国国家美术馆 · 术语“雅宴画”", "claim": "华托 1717 年的学院入选作被记为表现“une fête galante”，这一画种由华托带起", "url": "https://www.nationalgallery.org.uk/paintings/glossary/f%C3%AAtes-galantes"}, {"label": "法国国家档案馆 · 苏比斯府", "claim": "1735 年博夫朗建椭圆形楼阁，1736 年起专注室内装饰，召集布歇、纳图瓦尔、勒穆瓦纳、韦尔贝克特；椭圆形让拱窗把花园的光引进来；属 rocaille 风格", "url": "https://www.archives-nationales.culture.gouv.fr/lhotel-de-soubise"}, {"label": "英文维基百科 · 苏比斯府", "claim": "公主椭圆沙龙由博夫朗 1735–1740 年设计，位于二层公主套间；白底描金护墙板嵌镜面，檐口上方八幅《普绪喀的故事》出自纳图瓦尔；18 世纪以来少有改动；今为国家档案馆博物馆", "url": "https://en.wikipedia.org/wiki/H%C3%B4tel_de_Soubise"}, {"label": "英文维基百科 · 博夫朗", "claim": "博夫朗 1667 年 5 月 16 日生于南特，1754 年 3 月 19 日卒于巴黎；摄政风格与洛可可室内的主要创造者之一", "url": "https://en.wikipedia.org/wiki/Germain_Boffrand"}, {"label": "英文维基百科 · 纳图瓦尔", "claim": "纳图瓦尔 1700 年 3 月 3 日生，1777 年 8 月 23 日卒，以苏比斯府公主沙龙的《普绪喀的故事》组画闻名", "url": "https://en.wikipedia.org/wiki/Charles-Joseph_Natoire"}, {"label": "大都会艺术博物馆 · 《美的分析》图版一", "claim": "贺加斯《美的分析》图版一，1753 年 3 月 5 日，蚀刻与雕版，第三状态，纸张 38.8 × 50 cm，32.35(22)", "url": "https://www.metmuseum.org/art/collection/search/365314"}, {"label": "PMC · Hübner & Ufken 2022，贺加斯“美的线条”", "claim": "贺加斯在《美的分析》（1753）画了七条波浪线，指定第 4 条为“美的线条”，并引原文说明 5–7 过弯、1–3 过直", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8978312/"}, {"label": "古登堡计划 · 贺加斯《美的分析》原文", "claim": "第 9 章“用波浪线构图”：波浪线中只有一条可称“美的线条”，即图版一第 49 图中的第 4 条；5–7 过弯，1–3 过直", "url": "https://www.gutenberg.org/ebooks/51459"}, {"label": "老绘画陈列馆 · 布歇《蓬巴杜夫人》", "claim": "1756 年，布面油画，205 × 161 cm，HUW 18；布歇 1703–1770；她本人订画，身边是书、信、乐谱和素描；HypoVereinsbank 长期借展", "url": "https://www.sammlung.pinakothek.de/en/artwork/Dj4mX97G5A/francois-boucher/madame-de-pompadour"}, {"label": "卢浮宫 · 大卫《荷拉斯兄弟之誓》", "claim": "《荷拉斯兄弟在父亲手中宣誓》1784 年在罗马画成，INV 3692；1785 年运回巴黎，在当年沙龙展出", "url": "https://collections.louvre.fr/en/ark:/53355/cl010062239"}, {"label": "维基共享资源 · 主图文件页", "claim": "File:Fragonard, The Swing.jpg，4280 × 5373，来源 Oxford Art Online 华莱士收藏馆指南，{{PD-Art|PD-old-auto-expired|deathyear=1806}}", "url": "https://commons.wikimedia.org/wiki/File:Fragonard,_The_Swing.jpg"}, {"label": "维基共享资源 · 舟发西苔岛图片文件页", "claim": "据 C2RMF 图像调整，{{PD-Art|PD-old-auto-expired|deathyear=1721}}", "url": "https://commons.wikimedia.org/wiki/File:L%27Embarquement_pour_Cyth%C3%A8re,_by_Antoine_Watteau,_from_C2RMF_retouched.jpg"}, {"label": "维基共享资源 · 公主沙龙照片文件页", "claim": "Neoclassicism Enthusiast 2021 年 7 月 22 日自摄，CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Salon_ovale_de_la_princesse_in_the_H%C3%B4tel_de_Soubise_(11).jpg"}, {"label": "维基共享资源 · 美的分析图片文件页", "claim": "大都会艺术博物馆捐赠图像 DP827041，CC0", "url": "https://commons.wikimedia.org/wiki/File:The_Analysis_of_Beauty,_Plate_1_MET_DP827041.jpg"}, {"label": "维基共享资源 · 蓬巴杜夫人图片文件页", "claim": "来源 Google Arts & Culture，HUW 18，{{PD-Art|PD-old-auto-expired|deathyear=1770}}", "url": "https://commons.wikimedia.org/wiki/File:Madame_de_Pompadour.jpg"}]};

;
(window.EH_ROOMS=window.EH_ROOMS||{})["neoclassical"]={"id": "neoclassical", "zh": "新古典", "lat": "Neoclassicismus", "yrs": "c. 1760 – 1830", "one": "曲线被拉成直线，个人让位给誓言", "wall": "#ADA79D", "wallWhy": "墙面取罗马石灰华和灰泥的冷灰色，也就是画里那座柱廊的颜色。上一厅是粉彩和金色涡卷，这一厅把颜色退回石头；画框也用素净的石色，不用雕花金框，让三道拱和人物身上的直线自己撑起画面。墙色比画中的柱子浅两三档，拱洞里的暗处才压得住。", "ink": "dark", "frame": "stone", "art": {"img": "main.webp", "w": 2400, "h": 1871, "who": "雅克-路易·大卫", "whoLat": "Jacques-Louis David, 1748 – 1825", "title": "《贺拉斯兄弟之誓》", "short": "《贺拉斯兄弟之誓》", "meta": ["1786 年，布面油画；1784 年原作的缩小复制，据说学生吉罗代参与", "130.2 × 166.7 cm", "托莱多（美国俄亥俄州），托莱多艺术博物馆（1950.308）"], "credit": "Wikimedia Commons, File:Jacques-Louis David - Oath of the Horatii - Google Art Project.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, "lede": "大卫受国王委托画一个古罗马故事。他没有画厮杀，画的是厮杀之前的一句誓言。", "work": "两根柱子、三道拱，把画面分成三份，每份一组人。左边三兄弟叠成一个整体，腿蹬成弓步，一齐伸出右臂；中间的父亲高举三把剑，仰脸看着剑；右边的女人弯腰垂头，后面一位妇人搂着两个孩子。男人这边全是绷直的线：手臂、腿、长矛、剑刃。女人那边是垂下的弧线，和头上的拱一样。光从左上方斜射进来，背景沉在暗处，人物像浮雕一样排在前景一条窄窄的地面上。", "quote": ["此画长 13 法尺、高 10 法尺，是为国王画的。", "1785 年沙龙展目录第 103 号（据卢浮宫藏品档案，本展译）"], "origin": "1738 年起，那不勒斯国王在赫库兰尼姆开挖，1748 年又挖到庞贝，欧洲人开始成片看到古罗马城镇的街道、房屋和壁画。1755 年，温克尔曼出版《关于模仿希腊作品的思考》，把古希腊雕塑奉为最高典范。1774 年大卫赢得罗马奖，在罗马学了五年。1781 年底或 1782 年初，王室订下这幅画，原定题目是得胜的贺拉斯；大卫改画了古代史书里找不到的起誓一幕，1785 年在罗马完成，9 月送进巴黎沙龙。", "traits": [["轮廓清楚，笔触隐去", "线条先于色彩。人物轮廓像刻出来一样清楚，笔触抹平到几乎看不见，颜色服从素描，和洛可可松动、闪烁的笔法正好相反。"], ["古代是道德的榜样", "题材多取自古罗马史书和古希腊哲人的故事，服装、家具、建筑照古代遗物考证。要紧的不是古装，是古人面对抉择时的样子。"], ["像浮雕一样排开", "人物多用侧面，在前景一条浅台上从左到右排开，背后是素墙或柱廊。构图对称，分组清楚，远处站着也能一眼读完。"], ["公德压过私情", "画的多是为城邦、为原则舍弃个人的一刻：起誓、赴死、牺牲亲人。情感被压着不外露，代价留给观者自己去掂量。"]], "special": {"title": "把曲线拉直", "type": "oath", "text": "拖住一根还软着的曲线往外拉，它会绷直，吸附到网格上：这是本展的比喻，上一厅的 S 形曲线到这里被拉成了直线。三兄弟的手臂也交给你来摆齐。画里的三条手臂其实并不平行，从下到上一条比一条抬得高，微微张开，指尖都落在父亲手中的剑前。三个人像只伸出了一只手。", "labels": {"dragHint": "拉直一根曲线", "armsHint": "把三条手臂摆齐", "armsDone": "三只手，一个誓言", "skeleton": {"label": "骨架", "text": "两根柱子大致把画面三等分，三道拱各罩住一组人：左边三兄弟，中间父亲，右边女人和孩子。两侧墙上的石缝顺着透视汇向父亲握剑的拳头下方，落在剑身附近；三兄弟的手臂也都指向这一带。"}, "slider": {"label": "直线 / 曲线", "left": "直线", "right": "曲线", "textLine": "男人这一边：腿、手臂、长矛、剑刃都是直线，和身后的柱子一样硬。三兄弟向父亲起誓，要为罗马打败对方派出的三兄弟，要么得胜，要么战死。", "textCurve": "女人这一边：肩、背、垂下的头都是弧线，像头上的拱。白衣的卡米拉是贺拉斯家的女儿，许配给了对面的库里亚蒂兄弟之一；她身旁的萨宾娜是库里亚蒂家的女儿，嫁进了贺拉斯家。不管哪边赢，她们都要失去亲人。"}}, "guides": {"note": "像素坐标以 main.webp（2400 × 1871）为准，原点左上；box 为 [x0, y0, x1, y1]，点为 [x, y]。手量，误差约 ±15 px。详见 notes.md", "arches": [{"key": "left", "inner": [250, 196, 740, 445], "outer": [202, 150, 795, 445]}, {"key": "middle", "inner": [912, 196, 1425, 445], "outer": [862, 150, 1478, 445]}, {"key": "right", "inner": [1605, 196, 2100, 445], "outer": [1552, 150, 2160, 445]}], "columns": [{"key": "left", "abacus": [712, 420, 948, 443], "shaft": [757, 443, 915, 1340]}, {"key": "right", "abacus": [1402, 420, 1642, 443], "shaft": [1440, 443, 1590, 1340]}], "groups": {"brothers": [70, 550, 1070, 1745], "father": [935, 530, 1500, 1740], "women": [1450, 1010, 2400, 1740]}, "heads": {"brotherFront": [358, 650, 500, 850], "brotherGold": [500, 690, 660, 870], "brotherBack": [608, 700, 742, 850], "father": [1300, 715, 1440, 870]}, "arms": [{"key": "upper", "from": [845, 815], "tip": [1062, 735], "angleDeg": 20}, {"key": "middle", "from": [800, 850], "tip": [1060, 797], "angleDeg": 12}, {"key": "lower", "from": [660, 895], "tip": [1007, 867], "angleDeg": 5}], "swords": {"bundle": [980, 535, 1260, 1145], "fist": [1105, 700, 1160, 770], "openHand": [1020, 620, 1110, 705], "pommels": [[1150, 540], [1190, 580], [1180, 600]], "tips": [[990, 1050], [1030, 1110], [1085, 1140]]}, "vanishingPoint": [1110, 840], "women": {"camilla": [2050, 1080, 2370, 1735], "sabina": [1750, 1015, 2130, 1720], "motherChildren": [1450, 1040, 1850, 1670]}, "spear": [[75, 555], [367, 1733]], "thirdsX": [800, 1600], "columnAxesX": [836, 1515]}}, "works": [{"img": "w1.webp", "w": 1200, "h": 950, "who": "安杰莉卡·考夫曼", "whoLat": "Angelica Kauffman, 1741 – 1807", "title": "《格拉古之母科尔内利娅》", "meta": ["约 1785 年，布面油画", "101.6 × 127 cm", "里士满（美国弗吉尼亚州），弗吉尼亚美术馆（75.22）"], "note": "女客炫耀珠宝，她指着孩子：这就是我的珍宝。", "credit": "Wikimedia Commons, File:Kauffmann Cornelia mater Gracchorum.jpg — 来源 goethezeitportal.de，公有领域"}, {"img": "w2.webp", "w": 1200, "h": 795, "who": "雅克-路易·大卫", "whoLat": "Jacques-Louis David, 1748 – 1825", "title": "《苏格拉底之死》", "meta": ["1787 年，布面油画", "129.5 × 196.2 cm", "纽约，大都会艺术博物馆（31.45）"], "note": "一手伸向毒酒杯，一手指天，死前还在讲学。", "credit": "Wikimedia Commons, File:The Death of Socrates MET DT40.jpg — 来源 大都会艺术博物馆，CC0"}, {"img": "w3.webp", "w": 932, "h": 1200, "who": "雅克-路易·大卫", "whoLat": "Jacques-Louis David, 1748 – 1825", "title": "《马拉之死》", "meta": ["1793 年，布面油画", "165 × 128 cm", "布鲁塞尔，比利时皇家美术馆（inv. 3260）"], "note": "遇刺的革命者倒在浴缸里，上半幅只剩空墙。", "credit": "Wikimedia Commons, File:Jacques-Louis David - Marat assassinated - Google Art Project 2.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, {"img": "w4.webp", "w": 904, "h": 1200, "who": "安东尼奥·卡诺瓦", "whoLat": "Antonio Canova, 1757 – 1822", "title": "《珀耳修斯与美杜莎之首》", "meta": ["1804–1806 年，大理石", "高 242.6 cm", "纽约，大都会艺术博物馆（67.110.1）"], "note": "姿势仿《观景殿的阿波罗》，原像被拿破仑运走。", "credit": "Wikimedia Commons, File:Perseus with the Head of Medusa MET DP249451.jpg — 来源 大都会艺术博物馆，CC0"}], "chain": "之前：弗拉戈纳尔出自布歇门下；少年大卫也先投奔布歇，却被转给提倡古典的维安，再到罗马画古物。之后：他成了革命画家，后来又为拿破仑作画；他的学生把激情和异域带进画里，浪漫主义用雾和崇高冲散了网格。", "sources": [{"label": "卢浮宫 · 《贺拉斯兄弟之誓》藏品档案", "claim": "原作：1784 年，布面油画，3.3 × 4.25 m，INV 3692 / MR 1432；签名 “L. David faciebat / ROMAE anno / MDCCLXXXIV”；1781 年底或 1782 年初经昂吉维莱伯爵为路易十六订制，原定题目《得胜的贺拉斯》；1784 年 7 月获准赴罗马，约 1785 年上半年画成、7 月完成；8 月在罗马画室展出，1785 年沙龙第 103 号（“Ce tableau de 13 pieds de long, sur 10 de haut, est pour le Roi”），9 月中旬起展出；展后由画家复制一幅（今藏托莱多艺术博物馆）", "url": "https://collections.louvre.fr/ark:/53355/cl010062239"}, {"label": "托莱多艺术博物馆 · 《贺拉斯兄弟之誓》", "claim": "托莱多本（1950.308）：卢浮宫原作的缩小复制，沃德勒伊伯爵订购；据说学生吉罗代协助；130.2 × 166.7 cm；与原作的差别之一是女人脚边多了一支绕着纱的纺锤杆", "url": "https://emuseum.toledomuseum.org/objects/55069/the-oath-of-the-horatii"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图即托莱多本：commons_location = Toledo Art Museum，1786 年，130.2 × 166.2 cm，Google Art Project，6156 × 4800，公有领域；作者栏写 “Girodet，after David”", "url": "https://commons.wikimedia.org/wiki/File:Jacques-Louis_David_-_Oath_of_the_Horatii_-_Google_Art_Project.jpg"}, {"label": "英文维基百科 · 贺拉斯兄弟之誓", "claim": "故事出自李维《建城以来史》第一卷 24–26 节，起誓一幕是大卫的发明；白衣卡米拉许配给库里亚蒂兄弟之一，棕黄衣的萨宾娜是库里亚蒂家女儿、嫁入贺拉斯家；后面的妇人搂着两个孩子；男人用直线、女人用曲线；握剑的手位于透视灭点前方；1786 年与吉罗代合作的缩小复制本在托莱多", "url": "https://en.wikipedia.org/wiki/Oath_of_the_Horatii"}, {"label": "英文维基百科 · 雅克-路易·大卫", "claim": "大卫 1748 年生于巴黎，1825 年卒于布鲁塞尔；先投奔远亲布歇，布歇把他转给古典派的维安；1774 年获罗马奖，1775–1780 年在罗马；1787 年沙龙展出《苏格拉底之死》；后为拿破仑作画；学生格罗等", "url": "https://en.wikipedia.org/wiki/Jacques-Louis_David"}, {"label": "英文维基百科 · 让-奥诺雷·弗拉戈纳尔", "claim": "弗拉戈纳尔 1749 年起师从布歇", "url": "https://en.wikipedia.org/wiki/Jean-Honor%C3%A9_Fragonard"}, {"label": "英文维基百科 · 赫库兰尼姆", "claim": "1738 年那不勒斯国王查理为修夏宫开挖时重新发现赫库兰尼姆，此后开始系统发掘", "url": "https://en.wikipedia.org/wiki/Herculaneum"}, {"label": "英文维基百科 · 庞贝", "claim": "庞贝 1748 年被挖出，1763 年确认身份", "url": "https://en.wikipedia.org/wiki/Pompeii"}, {"label": "英文维基百科 · 温克尔曼", "claim": "温克尔曼 1755 年出版《关于模仿希腊作品的思考》（Gedanken über die Nachahmung der griechischen Werke），同年 11 月到罗马", "url": "https://en.wikipedia.org/wiki/Johann_Joachim_Winckelmann"}, {"label": "英文维基百科 · 新古典主义", "claim": "新古典主义约 1760 年兴起，反对洛可可；受温克尔曼著作和庞贝、赫库兰尼姆发现推动；古希腊绘画失传，画家借浮雕、瓶画等重建", "url": "https://en.wikipedia.org/wiki/Neoclassicism"}, {"label": "弗吉尼亚美术馆 · 《格拉古之母科尔内利娅》", "claim": "考夫曼（1741–1807）《科尔内利娅指着孩子们说他们是她的珍宝》约 1785 年，布面油画，101.6 × 127 cm，75.22；故事出自古罗马作家瓦勒里乌斯·马克西穆斯的记载", "url": "https://www.vmfa.museum/artworks/cornelia-mother-of-the-gracchi-pointing-to-her-children-as-her-treasures-71832"}, {"label": "维基共享资源 · 考夫曼图片文件页", "claim": "图片文件：1785 年，101 × 127 cm，弗吉尼亚美术馆；来源 goethezeitportal.de；PD-old-100", "url": "https://commons.wikimedia.org/wiki/File:Kauffmann_Cornelia_mater_Gracchorum.jpg"}, {"label": "大都会艺术博物馆 · 《苏格拉底之死》", "claim": "1787 年，布面油画，129.5 × 196.2 cm，31.45；大卫 1748–1825", "url": "https://www.metmuseum.org/art/collection/search/436105"}, {"label": "大都会艺术博物馆 · 《苏格拉底之死》细读", "claim": "画的是苏格拉底饮毒前停下来向弟子讲话的一刻；1787 年沙龙；床脚的柏拉图", "url": "https://www.metmuseum.org/perspectives/jacques-louis-david-death-of-socrates"}, {"label": "维基共享资源 · 苏格拉底之死图片文件页", "claim": "图片文件：大都会博物馆开放获取，CC0（本展裁去扫描黑边）", "url": "https://commons.wikimedia.org/wiki/File:The_Death_of_Socrates_MET_DT40.jpg"}, {"label": "比利时皇家美术馆 · 《马拉之死》", "claim": "《马拉遇刺》1793 年，布面油画，165 × 128 cm，inv. 3260；右下题 “A MARAT, / DAVID / L’AN DEUX”；1886 年遗赠，1893 年入馆", "url": "https://fine-arts-museum.be/fr/la-collection/jacques-louis-david-marat-assassine"}, {"label": "英文维基百科 · 马拉之死", "claim": "马拉 1793 年 7 月 13 日在浴缸中被夏洛特·科黛刺死；大卫当时是山岳派、公安委员会成员", "url": "https://en.wikipedia.org/wiki/The_Death_of_Marat"}, {"label": "维基共享资源 · 马拉之死图片文件页", "claim": "图片文件：Google Art Project，比利时皇家美术馆藏，PD-Art", "url": "https://commons.wikimedia.org/wiki/File:Jacques-Louis_David_-_Marat_assassinated_-_Google_Art_Project_2.jpg"}, {"label": "大都会艺术博物馆 · 《珀耳修斯与美杜莎之首》", "claim": "卡诺瓦（1757–1822）1804–1806 年，大理石，高 242.6 cm，67.110.1；塔尔诺夫斯基伯爵夫妇 1804 年订制的第二版；构图大体以《观景殿的阿波罗》为本，该像 1797 年被拿破仑军队从梵蒂冈运往巴黎；第一版（1797–1801）被教皇庇护七世买下，放在阿波罗像原来的位置", "url": "https://www.metmuseum.org/art/collection/search/204758"}, {"label": "大都会艺术博物馆 · 珀耳修斯专题", "claim": "珀耳修斯举起美杜莎的头；理想化的身体、从左臂垂下的斗篷，意在与古代名作一较高下", "url": "https://www.metmuseum.org/art/online-features/viewpoints/perseus"}, {"label": "维基共享资源 · 珀耳修斯图片文件页", "claim": "图片文件：大都会博物馆开放获取，CC0", "url": "https://commons.wikimedia.org/wiki/File:Perseus_with_the_Head_of_Medusa_MET_DP249451.jpg"}]};

