(window.EH_ROOMS=window.EH_ROOMS||{})["realism"]={"id": "realism", "zh": "现实主义", "lat": "Réalisme", "yrs": "c. 1840 – 1880", "one": "从山顶落回地面，画弯腰干活的人", "wall": "#B5AA97", "wallWhy": "墙面取画里远处那层尘土的暖灰，比画中的天空暗一档，好让那条窄窄的天空浮出来。转场时，墙和地面的分界线就是画里的地平线，它一路升高，整个展厅像低下了头；展签平放在地上，要低头去读。不加画框，让画里的麦茬和展厅的地面接在一起。从浪漫主义厅的冷灰雾色走进来，这一厅是傍晚田里的尘土。", "ink": "dark", "frame": "none", "art": {"img": "main.webp", "w": 2400, "h": 1796, "who": "米勒", "whoLat": "Jean-François Millet, 1814 – 1875", "title": "《拾穗者》", "short": "《拾穗者》", "meta": ["1857 年，布面油画", "83.5 × 110 cm", "巴黎，奥赛博物馆（RF 592）"], "credit": "Wikimedia Commons, File:Jean-François Millet - Gleaners - Google Art Project 2.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, "lede": "1857 年的巴黎沙龙上，三个拾麦穗的穷苦农妇占满了画面的前景，姿态庄重得像古典名画里的人物。", "work": "收割过的麦田里，三个农妇弯着腰，拾地上剩下的麦穗。左边戴蓝帽的伸手探向地面，中间裹红头巾的正捏起一根，右边那个半直起身，手里攥着一小把。奥赛博物馆把她们读作同一个动作的三步：弯下、拾起、直起。远处麦垛堆得像小山，马车满载，一大群人还在收割。夕阳从左边低低照来，照亮她们的手、后颈和背，人像石头雕出来的。", "quote": ["他那三个拾穗女野心大得吓人：摆出的架势，像掌管贫困的三位命运女神。她们是插在田里的破布稻草人，也像稻草人一样没有脸，一顶粗布头巾就算是脸了。", "圣维克托评 1857 年沙龙，《新闻报》 1857 年 8 月（本展译）"], "origin": "1848 年 2 月，巴黎的革命推翻了路易-菲利普的王朝，法国社会争的是民主改革，画家也把目光转向普通人。第二年 6 月，米勒带着家人离开巴黎，在枫丹白露森林边的巴比松村住下，此后多画身边的农民。1855 年，库尔贝的巨幅《画室》被世界博览会拒收，他自筹经费，在会场附近搭起“现实主义馆”，展目小册子的前言就题为《现实主义》。两年后，《拾穗者》在沙龙展出，有评论家嫌三个穷人太骄傲，据说还有人从她们身后看见了 1793 年的断头台。", "traits": [["普通人上大画", "农民、送葬的村民、路边碎石的工人，成了大画布上的主角。这种尺寸本来留给神话、宗教和帝王，把穷人画得这么大，很难不被看成一种表态。"], ["只画看得见的", "库尔贝 1861 年写道，绘画是一门具体的艺术，只能画真实存在的东西。神话和古代英雄退了场，题材就在画家自己的村子、田地和街上。"], ["不美化，也不煽情", "手是粗的，衣服是旧的，脸常常低着，或被帽檐遮住。画家既不把贫穷画得可爱，也不替人物哭诉，只把劳动本来的样子，放大了摆在观众面前。"], ["技法还在画室里", "深褐的底色、厚重的明暗、近乎黑色的阴影，多半仍在画室里凭素描和记忆慢慢画成。下一代画家要打破的，正是这套在画室里完成的办法。"]], "special": {"title": "你来拾穗", "type": "glean", "text": "按住画里的麦茬，你就弯下了腰；把手停在一根麦穗上，再坚持一会儿，它才会被拾起来。弯得越久，腰越酸，直起身也越来越慢。据奥赛博物馆的说明，拾穗的人只能在收割之后、日落之前进田，一根一根捡割麦时漏下的穗子。你攒下的这一把，就摆在远处的麦垛旁边比着看：那边堆成山的，是这片田主人的收成。", "hint": {"mouse": "在画里的麦茬上按住鼠标，弯下腰；把手停在一根麦穗上别松开，拾起它。拖动“地平线”，或用放大镜看看远处。", "touch": "手指按住画里的麦茬不放，弯下腰；停在一根麦穗上，拾起它。也可以按住“弯腰拾穗”。拖动“地平线”，或用放大镜看看远处。"}, "horizonText": ["米勒把地平线放得很高，天空只剩窄窄一条。两个弯腰的人，头都低在田里；直起身的那个，帽顶也只碰到地平线。她们四周只有土地。", "把地平线拉回中线，她们的背和头就伸进了天空，一下子像站在高处的英雄。米勒没有这样画，这是本展做的对照。"], "overseerText": "远处马背上的人，奥赛博物馆认为多半是田庄的管事：他替主人看着收割，也盯着拾穗的人守不守规矩。有他在，这片田属于谁，就不言自明了。", "lensHint": "拖动放大镜，看看远处。", "scaleNote": "同一比例：远处的麦垛，它脚下的人，和你手里的这一把", "labels": {"bend": "弯腰拾穗", "horizon": "地平线", "horizonHigh": "米勒的", "horizonMid": "中线", "lens": "远处有什么", "overseer": "马背上的监工", "count": "拾了", "unit": "根", "back": "腰酸了：直起身来，一次比一次慢。", "backRest": "直起身歇一会儿，腰会缓过来。", "done": "地上的麦穗拾完了。弯了这么久的腰，换来手里这一把。", "again": "再拾一遍"}, "guides": {"note": "像素坐标以 main.webp（2400 × 1796）为准，原点左上；box 为 [x0, y0, x1, y1]，点为 [x, y]，目测约 ±15 px。分层、麦穗位置以 cut/layers.json 为准，详见 notes.md", "horizonY": 533, "horizonLine": [[0, 552], [330, 549], [1000, 536], [1300, 531], [1700, 530], [2400, 531]], "women": {"left": [415, 690, 1000, 1290], "middle": [870, 750, 1580, 1400], "right": [1495, 521, 2090, 1565]}, "heads": {"left": [478, 810, 660, 945], "middle": [870, 870, 1040, 1040], "right": [1495, 521, 1640, 635]}, "hands": {"leftReach": [415, 1180, 525, 1275], "middlePick": [880, 1320, 965, 1405], "rightBundle": [1540, 1000, 1770, 1520]}, "overseer": [2080, 512, 2156, 596], "haystacks": [[328, 362, 554, 608], [520, 382, 742, 608], [1252, 476, 1422, 566]], "figureAtHaystacks": [562, 550, 592, 620], "cart": [690, 440, 1012, 640], "harvesters": [1000, 515, 1420, 605], "stook": [1236, 556, 1342, 672], "village": [1700, 470, 2400, 560], "birds": [1450, 0, 2130, 80], "stubble": [0, 1420, 2400, 1796]}}, "works": [{"img": "w1.webp", "w": 1200, "h": 551, "who": "库尔贝", "whoLat": "Gustave Courbet, 1819 – 1877", "title": "《奥尔南的葬礼》", "meta": ["1849–1850 年，布面油画", "315 × 668 cm", "巴黎，奥赛博物馆（RF 325）"], "note": "小城的一场葬礼，村民都按真人大小画出。", "credit": "Wikimedia Commons, File:Gustave Courbet - A Burial at Ornans - Google Art Project 2.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, {"img": "w2.webp", "w": 1200, "h": 614, "who": "罗莎·博纳尔", "whoLat": "Rosa Bonheur, 1822 – 1899", "title": "《尼韦奈的耕作》", "meta": ["1849 年，布面油画", "133 × 260 cm", "巴黎，奥赛博物馆（RF 64）"], "note": "国家订制的大画，主角是犁地的牛，人退成了配角。", "credit": "Wikimedia Commons, File:Rosa Bonheur - Ploughing in Nevers - Google Art Project.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, {"img": "w3.webp", "w": 1200, "h": 608, "who": "朱尔·布雷东", "whoLat": "Jules Breton, 1827 – 1906", "title": "《召回拾穗者》", "meta": ["1859 年，布面油画", "90.5 × 176 cm", "巴黎，奥赛博物馆（MI 289）"], "note": "拾穗女被画得体面动人，皇帝在沙龙上买下了它。", "credit": "Wikimedia Commons, File:Jules Breton - Calling in the Gleaners - Google Art Project.jpg — 来源 Google Arts & Culture，公有领域（PD-Art）"}, {"img": "w4.webp", "w": 1200, "h": 868, "who": "杜米埃", "whoLat": "Honoré Daumier, 1808 – 1879", "title": "《三等车厢》", "meta": ["1864 年，布面油画", "65.4 × 90.2 cm", "纽约，大都会艺术博物馆（29.100.129）"], "note": "挤在车厢里的穷人：老妇、喂奶的母亲、睡着的男孩。", "credit": "Wikimedia Commons, File:The Third-Class Carriage MET DT2142.jpg — 来源 大都会艺术博物馆，CC0"}], "chain": "之前：浪漫派让人站在山顶，面对雾海和崇高的自然，画的是自己的心境。之后：印象派接过“画眼前”，又往前走了一步，把画架搬到户外，去追某一刻的光和空气，这就是下一厅。", "sources": [{"label": "奥赛博物馆 · 藏品页《拾穗者》", "claim": "Des glaneuses，1857 年，布面油画，H. 83.5；L. 110 cm，RF 592，1890 年 Pommery 夫人保留用益权捐赠；1857 年沙龙第 1936 号；说明：十年研究的结果；三个人是同一动作的三个阶段（弯下、拾起、直起）；拾穗者获准在日落前匆匆进入收割过的田里，一根根捡漏下的麦穗；远处麦垛、麦捆、马车和收割的人群，尺度突变；夕阳的斜光让她们像雕塑；右边骑马的人“很可能是一位管事”，负责监督田庄的活计和拾穗规矩", "url": "https://www.musee-orsay.fr/fr/oeuvres/des-glaneuses-342"}, {"label": "法国国家图书馆 Gallica · 《新闻报》1857 年 8 月 4 日", "claim": "La Presse 1857 年 8 月 4 日第 2 版的沙龙评论，原文有“elles posent comme les trois Parques du paupérisme”“comme les épouvantails, elles n’ont pas de visage : une coiffe de bure leur en tient lieu”“elles ont trop d’orgueil”", "url": "https://gallica.bnf.fr/ark:/12148/bpt6k477753f"}, {"label": "法文维基百科 · Des glaneuses", "claim": "圣维克托原文：“Ses trois glaneuses ont des prétentions gigantesques : elles posent comme les trois Parques du paupérisme. Ce sont des épouvantails de haillons plantés dans un champ, et, comme les épouvantails, elles n'ont pas de visage : une coiffe de bure leur en tient lieu.”；右派评论视之为民众革命的威胁；米勒在沙伊观察农妇，或联想到《路得记》", "url": "https://fr.wikipedia.org/wiki/Des_glaneuses"}, {"label": "英文维基百科 · The Gleaners", "claim": "1854 年有一幅竖幅的同题画，1855 年有蚀刻版；1857 年沙龙首展，中上层观众起疑，一位评论者从中看出“1793 年断头台”的预兆（据 Kimmelman，《纽约时报》1999 年 8 月 27 日）", "url": "https://en.wikipedia.org/wiki/The_Gleaners"}, {"label": "《十九世纪艺术世界》· 里布纳《论米勒的一幅重画之作》", "claim": "“Fleeing a cholera outbreak in June of 1849, Millet permanently settled with his family in Barbizon.”（Jonathan P. Ribner，Nineteenth-Century Art Worldwide，2014 年春季号）", "url": "https://www.19thc-artworldwide.org/spring14/ribner-on-a-repainting-by-millet"}, {"label": "大都会艺术博物馆 · 19 世纪法国现实主义（专题文章，存档）", "claim": "现实主义运动约 1840 年起兴盛至 19 世纪后期；在推翻路易-菲利普王朝的 1848 年革命之后兴起，于拿破仑三世的第二帝国时期发展；描绘工人阶级的日常生活，拒绝学院的理想化古典和浪漫派的异域题材；库尔贝在 1849 年和 1850–1851 年沙龙展出的《奥尔南的葬礼》《碎石工》（已毁），用从前留给历史画的巨大尺幅画家乡的普通人；1849 年米勒离开巴黎定居巴比松", "url": "https://web.archive.org/web/20181213025459/https://www.metmuseum.org/toah/hd/rlsm/hd_rlsm.htm"}, {"label": "奥赛博物馆 · 藏品页《画室》", "claim": "《画室》（1854–1855 年，361 × 598 cm，RF 2257）原为 1855 年世界博览会而画，被拒后库尔贝自费搭建“现实主义馆”，在官方展会之外办个展，《奥尔南的葬礼》也在其中", "url": "https://www.musee-orsay.fr/en/artworks/latelier-du-peintre-927"}, {"label": "大英百科全书 · 库尔贝", "claim": "《画室》被 1855 年世界博览会评审团拒收后，库尔贝在一位朋友的资助下，在官方展会附近开设自己的“现实主义馆”；1849 年画《碎石工》，次年画《奥尔南的葬礼》", "url": "https://www.britannica.com/biography/Gustave-Courbet"}, {"label": "奥赛博物馆（存档）· 库尔贝自述", "claim": "1855 年现实主义馆展目小册子的前言题为“Réalisme”，常被视为现实主义宣言：“现实主义者的称号是被强加给我的……”", "url": "https://web.archive.org/web/2016/http://www.musee-orsay.fr/en/collections/courbet-dossier/courbet-speaks.html"}, {"label": "诺克林编《现实主义与艺术传统》· 库尔贝致学生的公开信", "claim": "1861 年 12 月 25 日致学生的公开信，刊于《星期日信使报》：“painting is an essentially concrete art and can only consist of the representation of real and existing things”", "url": "https://www.gettydocents.org/wp-content/uploads/Gustave-Courbet-Realist-Manifesto.pdf"}, {"label": "奥赛博物馆 · 藏品页《奥尔南的葬礼》", "claim": "Un enterrement à Ornans，1849–1850 年，布面油画，H. 315；L. 668 cm，RF 325；1850–1851 年沙龙第 661 号，1855 年现实主义馆第 2 号；村民按真人大小画出，这本是圣经和神话人物的特权，没有理想化；评论家斥其“粗俗的丑陋”", "url": "https://www.musee-orsay.fr/en/artworks/un-enterrement-ornans-924"}, {"label": "奥赛博物馆 · 藏品页《尼韦奈的耕作》", "claim": "Labourage nivernais，1849 年，布面油画，H. 133；L. 260 cm，RF 64；国家 1848 年订制，原定给里昂博物馆，后留在巴黎卢森堡宫博物馆；主角是牛，放牛人只是小小的人影；评论几乎一致叫好", "url": "https://www.musee-orsay.fr/en/artworks/labourage-nivernais-68"}, {"label": "奥赛博物馆 · 藏品页《召回拾穗者》", "claim": "Le Rappel des glaneuses，1859 年，布面油画，H. 90.5；L. 176 cm，MI 289；画的是拾穗女收工离田，而非米勒两年前那样的劳作；画家把场面完全理想化；1859 年沙龙大受称赞，欧仁妮皇后安排以拿破仑三世的内廷经费购入，1862 年由皇帝赠给卢森堡宫博物馆", "url": "https://www.musee-orsay.fr/en/artworks/le-rappel-des-glaneuses-888"}, {"label": "大都会艺术博物馆 · 《三等车厢》", "claim": "The Third-Class Carriage，杜米埃，1864 年，布面油画，65.4 × 90.2 cm，29.100.129，H. O. 哈夫迈耶夫人遗赠，1929 年", "url": "https://www.metmuseum.org/art/collection/search/436095"}, {"label": "维基共享资源 · 主图文件页", "claim": "Jean-François Millet - Gleaners - Google Art Project 2.jpg，5354 × 4006，公有领域，来源 Google Arts & Culture", "url": "https://commons.wikimedia.org/wiki/File:Jean-Fran%C3%A7ois_Millet_-_Gleaners_-_Google_Art_Project_2.jpg"}, {"label": "维基共享资源 · 四件对照作品的文件页", "claim": "库尔贝《奥尔南的葬礼》、博纳尔《尼韦奈的耕作》、布雷东《召回拾穗者》均为 Google Art Project 扫描，公有领域；杜米埃《三等车厢》由大都会艺术博物馆捐赠，CC0", "url": "https://commons.wikimedia.org/wiki/File:The_Third-Class_Carriage_MET_DT2142.jpg"}]};

